// Worktrees page Alpine component.
// Finalized commit-first review queue with full-screen commit/change review.
//
// Capability-layer types flow in from `agents/capabilities/github/schemas.py`
// via the generated `capability-github.d.ts` (auto-regenerated by
// `graph set typegen --schemas <refs> --name capability-github`). The
// JSDoc @typedef imports below pull each interface in for use as
// `@param` / `@returns` type hints on the methods that consume
// capability data — replacing hand-tracked field shape with codegen-
// driven types so any Python schema edit shows up here at the next
// regen (Bead 3D).
//
// @typedef {import('../types/capability-github').CheckEntryV1} CheckEntryV1
// @typedef {import('../types/capability-github').ReviewPayloadV1} ReviewPayloadV1

(function () {
  const _pathMeasureCanvas =
    typeof document !== 'undefined' ? document.createElement('canvas') : null;
  const _pathMeasureContext = _pathMeasureCanvas ? _pathMeasureCanvas.getContext('2d') : null;

  function _shortSha(sha) {
    return sha ? sha.slice(0, 7) : '';
  }

  function _b64ToBytes(b64) {
    const bin = atob(b64);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }

  function _parseCommitPayload(text) {
    // commit object bytes -> {subject, body, author}; headers end at first blank line
    const lines = text.split('\n');
    let i = 0, author = '';
    for (; i < lines.length; i++) {
      if (lines[i] === '') { i++; break; }
      if (lines[i].startsWith('author ')) {
        const m = lines[i].slice(7).match(/^(.*<[^>]*>)/);
        author = m ? m[1] : lines[i].slice(7);
      }
    }
    const message = lines.slice(i).join('\n');
    const nl = message.indexOf('\n');
    const subject = (nl >= 0 ? message.slice(0, nl) : message).trim();
    const body = nl >= 0 ? message.slice(nl + 1).replace(/^\n+/, '') : '';
    return { subject, body, author };
  }

  function _toast(message, type) {
    if (window.showToast) {
      window.showToast(message, type || 'error');
    }
  }

  function _linkTtlText(ttl) {
    if (!ttl) return 'No expiration';
    // Decompose ANY positive integer of seconds into readable components:
    // 3600 -> "1 Hour", 604800 -> "1 Week", 10420 -> "2 Hours 53 Minutes 40 Seconds".
    const units = [[604800, 'Week'], [86400, 'Day'], [3600, 'Hour'], [60, 'Minute'], [1, 'Second']];
    const parts = [];
    let rem = ttl;
    for (const [secs, name] of units) {
      const n = Math.floor(rem / secs);
      if (n > 0) {
        parts.push(n + ' ' + name + (n === 1 ? '' : 's'));
        rem -= n * secs;
      }
    }
    return parts.join(' ');
  }

  const _LINK_DURATION_VALUES = new Set([
    '604800', '2592000', '31536000',
  ]);


  function _linkPayloadWithTtl(payload, ttl) {
    const next = JSON.parse(JSON.stringify(payload || {}));
    const meta = Object.assign({}, next.meta || {});
    if (ttl === null) delete meta.ttl;
    else meta.ttl = ttl;
    if (Object.keys(meta).length) next.meta = meta;
    else delete next.meta;
    return next;
  }

  function _matchingApprovalAuthority(req) {
    const session = window.AutonomyNetworkSession;
    if (!session || typeof session.state !== 'function') return false;
    const state = session.state();
    // Publish carries the org uuid inside the staged payload; revoke's
    // payload is empty by contract, so its rows expose the frozen
    // binding's uuid as req.orgUuid instead.
    const expectedOrg = req.orgUuid || (
      req.registryRequest && req.registryRequest.payload &&
      req.registryRequest.payload.org);
    // One personal sign-on carries a persona per organization, so authority
    // for THIS action is one row of the session, not the whole session.
    return !!(state && state.signedIn && (state.orgs || []).some(
      (entry) => entry.live && entry.org === expectedOrg));
  }

  // Gate 2 unlocks org authority only for the concrete action being reviewed.
  // The passphrase and root plaintext stay inside network-signon.js; this
  // function receives only a signed envelope back.
  // recovery_policy is 'none' (operator decision: recovery is a sovereign,
  // root-mutable policy — the root holder can ADD recovery later via a
  // root-signed policy update). NB the policy-update path that makes 'none'
  // reversible is a SEPARATE registry companion (registry.auto.network +
  // redeploy); until it deploys, 'none' is not yet reversible in the LIVE
  // registry, so this flow must not promise "add recovery later" in the UI.
  const INLINE_RECOVERY_POLICY = 'none';

  // Inline first-publish registration (register-before-freeze). Reuses the
  // EXISTING root-signed registration ceremony via exposed internals — no new
  // crypto: decrypt the org armor with the operator's password, sign a
  // root-direct registration envelope, POST it to the server route (which
  // verifies signer==root_pub, matches the stored key, and forwards to the
  // registry that verifies the signature and returns the binding). The root
  // plaintext is zeroed before this returns (I1).
  async function _registerOrgInline(req) {
    if (!INLINE_RECOVERY_POLICY) {
      throw new Error(
        'First-publish registration is not enabled yet — the organization ' +
        'recovery policy is still being decided. Register from the ' +
        'getting-started flow for now.');
    }
    const session = window.AutonomyNetworkSession;
    const identity = window.AutonomyNetworkIdentity;
    if (!session || !session._internals || !identity || !identity._internals) {
      throw new Error('Registration is unavailable in this browser. Reload and try again.');
    }
    const S = session._internals, I = identity._internals;
    const orgHeaders = req.orgSlug ? { 'X-Graph-Org': req.orgSlug } : {};
    const orgQ = req.orgSlug ? ('?org=' + encodeURIComponent(req.orgSlug)) : '';
    const keyResp = await fetch('/api/network/org-key' + orgQ, { headers: orgHeaders });
    if (!keyResp.ok) {
      throw new Error('Could not load this organization\'s signing key (' + keyResp.status + ').');
    }
    const orgKey = await keyResp.json();
    if (!orgKey.armored_private_key && !orgKey.sealed_root_key) {
      throw new Error('This organization has no signing key to register.');
    }
    // Open the root the same way the signer does — handles both the
    // password-armored key and the sealed_root_key scheme (unsealed via the
    // personal root). Returns the same {seed, rootPub} shape either way.
    const opened = await S.openOrgRoot(orgKey, req.password);
    let rootKey = null;
    try {
      rootKey = await I.importSigningKey(opened.seed);
      const payload = {
        org_uuid: crypto.randomUUID(),
        root_pub: opened.rootPub,
        recovery_policy: INLINE_RECOVERY_POLICY,
      };
      const envelope = await I.signRegistration(rootKey, opened.rootPub, payload);
      const resp = await fetch('/api/network/register', {
        method: 'POST',
        headers: Object.assign({ 'Content-Type': 'application/json' }, orgHeaders),
        body: JSON.stringify({ org: req.orgSlug, envelope: envelope }),
      });
      const body = await resp.json().catch(function () { return {}; });
      if (!resp.ok || body.ok === false) {
        throw new Error(body.error || ('Registration was refused (' + resp.status + ').'));
      }
    } finally {
      if (opened && opened.seed) { opened.seed.fill(0); opened.seed = null; }
      rootKey = null;   // I1: drop the root; the armor is the survivor
    }
  }

  async function _signLinkDecision(self, req) {
    let rr = req.registryRequest;
    const session = window.AutonomyNetworkSession;
    const signer = window.AutonomyNetworkSigner;
    if (!session || typeof session.signOn !== 'function' ||
        !signer || typeof signer.signRegistryRequest !== 'function') {
      throw new Error('Approval is unavailable in this browser. Reload the dashboard and try again.');
    }
    if (typeof session.ready === 'function') await session.ready();

    // Register-before-freeze: a keyed-but-unregistered org registers its
    // EXISTING key inline (the password just entered unlocks it), then a
    // re-enrich freezes the publish against the now-live binding. Nothing is
    // frozen or executed before the binding exists, so the confused-deputy
    // execute path is untouched.
    if (req.registrationRequired && !rr) {
      if (!req.password) throw new Error('Enter your organization password to continue.');
      // On-the-fly registration: register this org's EXISTING key inline in
      // the SAME Approve, invisibly. auto.network routes scope by the
      // X-Graph-Org header (a bare ?org= is refused cross-org without it), so
      // every call below carries it. Only SKIP registration if the org is
      // DEFINITIVELY already bound (a valid 200 binding from a prior half-
      // completed Approve); ANY other response (404, a scope 403, an error)
      // means "not confirmed bound" -> register. Never guess "bound" from a
      // non-200 and silently skip.
      const orgHeaders = req.orgSlug ? { 'X-Graph-Org': req.orgSlug } : {};
      const bq = req.orgSlug ? ('?org=' + encodeURIComponent(req.orgSlug)) : '';
      let alreadyBound = false;
      try {
        const b = await fetch('/api/network/binding' + bq, { headers: orgHeaders });
        if (b.ok) {
          const bj = await b.json().catch(function () { return {}; });
          alreadyBound = !!(bj && bj.org_uuid && bj.root_pub && bj.registry_url);
        }
      } catch (e) { /* unreachable -> treat as not bound, register */ }
      if (!alreadyBound) await _registerOrgInline(req);
      // Wait for the publish request to freeze against the now-live binding
      // (covers read-after-write timing). Invisible -- it just completes; no
      // "try again" is ever surfaced to the operator.
      for (let attempt = 0; attempt < 15 && !rr; attempt++) {
        const refreshed = await (await fetch(
          '/api/approvals/' + encodeURIComponent(req.id))).json();
        rr = refreshed && refreshed.registry_request;
        if (!rr) await new Promise(function (resolve) { setTimeout(resolve, 200); });
      }
      if (!rr) {
        throw new Error('Registered your organization, but the publish request '
          + 'did not prepare against the new binding.');
      }
      req.registryRequest = rr;
    }
    if (!rr) {
      throw new Error('This request is missing its auto.network details. Close it and try again.');
    }

    let retained = _matchingApprovalAuthority(req);
    if (!retained) {
      if (!req.password) throw new Error('Enter your organization password to continue.');
      try {
        await session.signOn(req.password, { org: req.orgSlug });
      } catch (error) {
        const message = String((error && error.message) || error || '');
        if (error && error.status === 404 && /org|identity|key/i.test(message)) {
          const missing = new Error(
            'This organization is not ready for approvals yet. Set up its signing authority and try again.');
          missing.code = 'ORG_KEY_NOT_CONFIGURED';
          throw missing;
        }
        if (/passphrase|password|decrypt|authentication/i.test(message)) {
          throw new Error('That password did not work. Try again.');
        }
        throw error;
      }
      retained = _matchingApprovalAuthority(req);
      if (!retained) {
        req.password = '';
        await session.signOut();
        throw new Error('The unlocked authority does not match this organization.');
      }
    }

    const isRevoke = req.op === 'revoke';
    const isOrgJoin = !isRevoke && rr.payload && rr.payload.target_type === 'org:join';
    let ttl = null;
    let payload;
    if (isRevoke) {
      // Registry contract: revoke envelopes carry an EMPTY payload — the
      // server refuses to forward anything else.
      payload = {};
    } else if (isOrgJoin) {
      const invitation = await import('../ceremony/invitation.js');
      payload = invitation.buildOrgJoinGrantPayload({
        orgUuid: rr.payload.org,
        inviteId: rr.payload.invite_ref,
        inviteExpiry: rr.payload.expires_at,
      });
      if (rr.payload.meta && Object.keys(rr.payload.meta).length) {
        payload.meta = JSON.parse(JSON.stringify(rr.payload.meta));
      }
    } else {
      ttl = req.duration === 'none' ? null
        : (req.duration === 'custom'
          ? req.customDurationSeconds
          : Number(req.duration));
      payload = _linkPayloadWithTtl(rr.payload, ttl);
    }
    // D19 routing: share links publish/revoke ride the org tunnel, so the
    // dashboard authenticates them LOCALLY and verifies this signature over
    // fixed proof-of-possession bytes (TUNNEL + a control path), NOT the
    // registry's method/path. org:join keeps the HTTP registry bytes (it
    // still travels to POST /v1/links). The executor's
    // _verify_local_publish_authority reconstructs the SAME bytes, so the
    // two sides must agree here (Codex D19 finding #3).
    const isShareLink = !isOrgJoin && (
      isRevoke ? (req.targetType && req.targetType !== 'org:join') : true);
    let signMethod = rr.method;
    let signPath = rr.path;
    if (isShareLink) {
      signMethod = 'TUNNEL';
      signPath = isRevoke ? '/control/revoke-link' : '/control/create-link';
    }
    try {
      let envelope;
      try {
        envelope = await signer.signRegistryRequest(
          signMethod, signPath, payload, { org: req.orgSlug });
      } catch (error) {
        throw new Error('This approval could not be signed. Unlock it again and retry.');
      }
      return (isOrgJoin || isRevoke) ? { envelope } : { envelope, ttl };
    } finally {
      // Unchecked is deliberately one action only. Checked retains the
      // non-extractable authority, never the password; Lock clears this same
      // AutonomyNetworkSession store.
      req.password = '';
      if (!req.allowSessionApprovals) await session.signOut();
    }
  }

  // Dashboard access is personal authority, not organization authority. Open
  // the password-armored personal root locally, sign the exact server-frozen
  // grant, and destroy the plaintext seed before returning. The decision body
  // carries only the grant and detached signature; the password never leaves
  // the browser.
  async function _signDashboardAccessDecision(self, req) {
    const { signDashboardAccessGrant } = await import(
      '../ceremony/dashboard-access.js'
    );
    return signDashboardAccessGrant(req.grant);
  }

  // Fleet admission is personal-root authority. The browser opens the
  // encrypted personal armor, mints the durable roster statement and the
  // transient channel approval, and hands only those signed public records to
  // the generic rendezvous. fleet-enrollment.js zeroes the root seed on every
  // exit, including validation and signing failures.
  async function _signFleetAdmissionDecision(self, req) {
    const machineName = typeof req.machineName === 'string'
      ? req.machineName.trim() : '';
    if (!machineName) {
      throw new Error('Enter a name for this machine.');
    }
    if (Array.from(machineName).length > 80 || /[\x00-\x1f\x7f]/.test(machineName)) {
      throw new Error('Machine name must be 1–80 characters without ASCII controls.');
    }
    const staged = req.fleet;
    if (!staged || !staged.request || !staged.channelBinding ||
        !Number.isSafeInteger(staged.issuedAt)) {
      throw new Error('This machine request has no server-frozen enrollment context.');
    }
    // ONE common factor-aware unlock — password, passkey, or both, chosen per
    // the armor's own factors. No password field on this approval card anymore.
    const { openRoot } = await import('../ceremony/open-root.js');
    const opened = await openRoot({
      title: 'Add this machine?',
      detail: 'Unlock your personal root to approve this machine.',
    });
    if (!opened) throw new Error('Approval cancelled.');
    try {
      if (opened.rootPub !== staged.personalRootPub) {
        throw new Error('This request belongs to a different personal fleet.');
      }
      const ceremony = await import('../ceremony/fleet-enrollment.js');
      const evidence = await ceremony.mintFleetEnrollmentEvidence({
        personalRootSeed: opened.seed,
        rootPub: opened.rootPub,
        request: staged.request,
        channelBinding: staged.channelBinding,
        localBootstrapMachineId: staged.localBootstrapMachineId || null,
        issuedAt: staged.issuedAt,
        seq: 0,
      });
      // The ceremony zeroed the same Uint8Array. Drop our reference so the
      // finally block cannot imply that a second live copy exists.
      opened.seed = null;
      req.password = '';
      const decision = {
        machine_name: machineName,
        approval: evidence.approval,
        roster_entry: evidence.rosterEntry,
      };
      if (evidence.localRosterEntry) {
        decision.local_roster_entry = evidence.localRosterEntry;
        decision.local_runtime = evidence.localRuntime;
      }
      return decision;
    } finally {
      if (opened && opened.seed) {
        opened.seed.fill(0);
        opened.seed = null;
      }
    }
  }

  async function _jsonOrError(resp) {
    const data = await resp.json().catch(() => ({}));
    if (!resp.ok) {
      const err = new Error(data.message || data.error || ('HTTP ' + resp.status));
      err.status = resp.status;
      err.payload = data;
      throw err;
    }
    return data;
  }

  function _commitStats(commit) {
    if (commit && commit.stats) return commit.stats;
    const files = (commit && commit.files) || [];
    return {
      files: files.length,
      additions: files.reduce((sum, file) => sum + (file.additions || 0), 0),
      deletions: files.reduce((sum, file) => sum + (file.deletions || 0), 0),
    };
  }

  function _normalizeRows(rows) {
    return (rows || []).map(row => ({
      ...row,
      clone_stale: !!row.clone_stale,
      rebase_required: !!row.rebase_required,
      commits: (row.commits || []).map(commit => ({
        ...commit,
        files: commit.files || [],
        stats: _commitStats(commit),
      })),
      dirty_files: row.dirty_files || [],
      dirty_count: (typeof row.dirty_count === 'number')
        ? row.dirty_count
        : (row.dirty_files || []).length,
    }));
  }

  function _normalizePatchPath(value) {
    if (!value) return '';
    let path = String(value).trim();
    if (path === '/dev/null') return '';
    path = path.replace(/^a\//, '').replace(/^b\//, '');
    return path;
  }

  function _parseUnifiedPatch(patch) {
    if (!patch) return [];
    const files = [];
    const lines = String(patch).split('\n');
    let current = null;
    let oldLine = 0;
    let newLine = 0;
    let inHunk = false;

    function pushCurrent() {
      if (!current) return;
      current.path = current.path || current.newPath || current.oldPath || '';
      files.push(current);
    }

    lines.forEach(raw => {
      if (raw.startsWith('diff --git ')) {
        pushCurrent();
        current = {
          oldPath: '',
          newPath: '',
          path: '',
          lines: [],
        };
        inHunk = false;
        return;
      }

      if (!current) return;

      if (raw.startsWith('--- ')) {
        current.oldPath = _normalizePatchPath(raw.slice(4));
        return;
      }

      if (raw.startsWith('+++ ')) {
        current.newPath = _normalizePatchPath(raw.slice(4));
        current.path = current.newPath || current.oldPath || current.path;
        return;
      }

      if (raw.startsWith('@@')) {
        const match = raw.match(/^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/);
        if (!match) return;
        oldLine = Number(match[1]);
        newLine = Number(match[2]);
        inHunk = true;
        return;
      }

      if (!inHunk) return;
      if (raw.startsWith('\\ No newline at end of file')) return;
      if (!raw.length) return;

      const marker = raw.charAt(0);
      const text = raw.slice(1);
      if (marker === '+') {
        current.lines.push({
          kind: 'add',
          oldNo: '',
          newNo: newLine,
          text,
        });
        newLine += 1;
        return;
      }
      if (marker === '-') {
        current.lines.push({
          kind: 'del',
          oldNo: oldLine,
          newNo: '',
          text,
        });
        oldLine += 1;
        return;
      }
      if (marker === ' ') {
        current.lines.push({
          kind: 'context',
          oldNo: oldLine,
          newNo: newLine,
          text,
        });
        oldLine += 1;
        newLine += 1;
      }
    });

    pushCurrent();
    return files.filter(file => file.path);
  }

  function _escapeHtml(value) {
    return String(value)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function _diffLanguageForPath(path) {
    if (!path) return '';
    const name = String(path).split('/').pop().toLowerCase();
    const basenameMap = {
      'dockerfile': 'dockerfile',
      'makefile': 'makefile',
      'gnumakefile': 'makefile',
      'cmakelists.txt': 'cmake',
      'jenkinsfile': 'groovy',
    };
    if (basenameMap[name]) return basenameMap[name];

    const extensionMap = {
      'bash': 'bash',
      'c': 'c',
      'cc': 'cpp',
      'cpp': 'cpp',
      'cs': 'csharp',
      'css': 'css',
      'cxx': 'cpp',
      'go': 'go',
      'gradle': 'groovy',
      'groovy': 'groovy',
      'h': 'c',
      'hh': 'cpp',
      'hpp': 'cpp',
      'htm': 'xml',
      'html': 'xml',
      'ini': 'ini',
      'java': 'java',
      'js': 'javascript',
      'json': 'json',
      'jsx': 'javascript',
      'kt': 'kotlin',
      'kts': 'kotlin',
      'less': 'less',
      'lua': 'lua',
      'mjs': 'javascript',
      'md': 'markdown',
      'php': 'php',
      'properties': 'properties',
      'py': 'python',
      'rb': 'ruby',
      'rs': 'rust',
      'scss': 'scss',
      'sh': 'bash',
      'sql': 'sql',
      'svg': 'xml',
      'svelte': 'svelte',
      'toml': 'toml',
      'ts': 'typescript',
      'tsx': 'typescript',
      'txt': 'plaintext',
      'vue': 'xml',
      'xml': 'xml',
      'yaml': 'yaml',
      'yml': 'yaml',
      'zsh': 'bash',
    };
    const parts = name.split('.');
    for (let idx = parts.length - 1; idx >= 1; idx -= 1) {
      const language = extensionMap[parts[idx]];
      if (language) return language;
    }
    return '';
  }

  function _highlightDiffText(path, text) {
    if (text == null || text === '') return '&nbsp;';
    const source = String(text);
    const hljs = window.hljs;
    if (!hljs) return _escapeHtml(source);
    const language = _diffLanguageForPath(path);
    try {
      if (language && hljs.getLanguage(language)) {
        return hljs.highlight(source, { language, ignoreIllegals: true }).value || '&nbsp;';
      }
    } catch (_) {
      // Fall through to escaped plaintext below.
    }
    return _escapeHtml(source);
  }

  function _patchIndex(patch) {
    const index = {};
    _parseUnifiedPatch(patch).forEach(file => {
      index[file.path] = (file.lines || []).map(line => ({
        ...line,
        html: _highlightDiffText(file.path, line.text),
      }));
    });
    return index;
  }

  function _fontForElement(el) {
    const style = window.getComputedStyle(el);
    return (
      style.font ||
      [
        style.fontStyle,
        style.fontVariant,
        style.fontWeight,
        style.fontSize,
        style.fontFamily,
      ].join(' ')
    );
  }

  function _fitPathToWidth(path, width, el) {
    if (!path || !_pathMeasureContext || !width) return path || '';
    _pathMeasureContext.font = _fontForElement(el);
    if (_pathMeasureContext.measureText(path).width <= width) return path;

    const ellipsis = '...';
    if (_pathMeasureContext.measureText(ellipsis).width >= width) return ellipsis;

    let low = 0;
    let high = path.length;
    let best = ellipsis;

    while (low <= high) {
      const keep = Math.floor((low + high) / 2);
      const candidate = ellipsis + path.slice(path.length - keep);
      if (_pathMeasureContext.measureText(candidate).width <= width) {
        best = candidate;
        low = keep + 1;
      } else {
        high = keep - 1;
      }
    }

    return best;
  }

  document.addEventListener('alpine:init', () => {
    Alpine.data('worktreesPage', (opts) => ({
      _mode: (opts && opts.mode) || 'page',
      rows: [],
      // Org scoping: the page shows exactly one organization at a time
      // (no "all" mode). ``orgs`` comes from /api/worktrees/orgs;
      // ``selectedOrg`` persists across visits. Until an org is chosen
      // the page shows the org picker and fetches no rows.
      orgs: [],
      selectedOrg: '',
      orgsLoading: true,
      orgMenuOpen: false,
      loading: true,
      refreshing: false,
      // Per-row force-refresh state for the review overlay's Refresh
      // button. Distinct from the page-level ``refreshing`` flag so a
      // background page refresh doesn't mark the overlay's button as
      // working — they're independent paths now (top-level is
      // local-git only; per-row is the operator's force-GET).
      rowRefreshing: false,
      cardRefreshing: {},
      detailLoading: false,
      dirtyDetailLoading: false,
      error: '',
      lastUpdated: '',
      viewMode: 'commits',
      selectedCommit: null,
      // commit-signing overlay state
      signPassphrase: '',
      signing: false,
      signError: null,
      signPrompt: false,      // is the passphrase entry step showing
      signRemember: false,    // "remember for this session" checkbox
      signHasRemembered: false, // a valid remembered passphrase exists (skip prompt)
      // generic approval overlay (non-commit kinds, e.g. jira_write):
      // { id, kind, session, title, actionLabel, op, target, bodyMarkdown, fields }
      approvalRequest: null,
      approvalBusy: false,
      selectedDirtyRow: null,
      confirmDiscardRow: null,
      showDiff: false,
      mergeState: 'idle',
      mergeBurstActive: false,
      mergeBurstSeed: 0,
      poofingRowKey: '',
      // Celebration timings, kept in sync with the CSS in worktrees.html:
      //   .merge-confetti-piece — 1300ms animation + up to 90ms per-piece delay
      //   .merge-confetti-glow  — 1100ms animation
      //   .poofing-card         — 420ms animation
      // The burst window has to outlast the slowest piece (1300+90 = 1390ms)
      // and the overlay-dismissal has to happen *after* the window closes,
      // otherwise the confetti DOM unmounts mid-animation. 1500ms gives
      // ~110ms of paint headroom on top of the longest piece path. Poof
      // start is delayed so the row card doesn't visually shrink while the
      // confetti is still arcing — confetti reads, then the row poofs.
      _BURST_WINDOW_MS: 1500,
      _POOF_START_MS: 900,
      _POOF_DURATION_MS: 420,
      rebaseRequiredDialog: null,
      rebaseRequesting: false,
      // Per-row rebase status, keyed by ``rowKey(row)``. Each entry is
      // ``{ state, error, optimistic }`` where ``state`` is one of
      // ``'awaiting' | 'in_progress' | 'done' | 'failed'``. ``awaiting``
      // is the optimistic local placeholder set when the operator clicks
      // Request Rebase — it covers the gap between the dashboard
      // directive append and
      // the agent's first ``WorktreeRebaseStatusV1`` write, then the
      // setting.changed callback overwrites it with the agent's true
      // state. ``optimistic`` flags an entry as locally-set so the
      // setting subscription handler can clear it on first transition.
      rebaseStatus: {},
      _rebaseStatusUnsubs: [],
      _RebaseStatusSchema: null,
      _RebaseDirective: null,
      cherryPicking: false,
      commitStickyTop: 0,
      commitFileRowStickyTop: 0,
      reviewTitlePinned: false,
      pathMeasureTick: 0,
      cleaning: {},
      syncingBase: {},
      _timer: null,
      _resizeHandler: null,
      _commitStickyResizeObserver: null,
      _reviewTitleObserver: null,
      _commitStickyRaf: 0,
      confettiPieces: [
        { id: 1,  dx: -148, dy: -82,  rot: -180, delay: 0,  color: '#818cf8' },
        { id: 2,  dx: -118, dy: -116, rot: -120, delay: 18, color: '#34d399' },
        { id: 3,  dx: -88,  dy: -78,  rot: -160, delay: 42, color: '#f9a8d4' },
        { id: 4,  dx: -38,  dy: -134, rot: -90,  delay: 0,  color: '#fcd34d' },
        { id: 5,  dx: -14,  dy: -94,  rot: -70,  delay: 32, color: '#e879f9' },
        { id: 6,  dx: 22,   dy: -142, rot: 88,   delay: 15, color: '#60a5fa' },
        { id: 7,  dx: 56,   dy: -84,  rot: 132,  delay: 48, color: '#34d399' },
        { id: 8,  dx: 94,   dy: -126, rot: 160,  delay: 0,  color: '#fb7185' },
        { id: 9,  dx: 132,  dy: -92,  rot: 210,  delay: 28, color: '#818cf8' },
        { id: 10, dx: -160, dy: -28,  rot: -140, delay: 55, color: '#f472b6' },
        { id: 11, dx: 158,  dy: -30,  rot: 152,  delay: 60, color: '#facc15' },
        { id: 12, dx: -72,  dy: -158, rot: -220, delay: 24, color: '#38bdf8' },
        { id: 13, dx: 72,   dy: -160, rot: 240,  delay: 36, color: '#a78bfa' },
        { id: 14, dx: 0,    dy: -176, rot: 180,  delay: 12, color: '#4ade80' },
        { id: 15, dx: -132, dy: -52,  rot: -260, delay: 70, color: '#fde047' },
        { id: 16, dx: 138,  dy: -56,  rot: 280,  delay: 8,  color: '#22d3ee' },
        { id: 17, dx: -50,  dy: -52,  rot: -100, delay: 90, color: '#f97316' },
        { id: 18, dx: 50,   dy: -50,  rot: 110,  delay: 80, color: '#a3e635' },
        { id: 19, dx: -100, dy: -160, rot: -300, delay: 50, color: '#ec4899' },
        { id: 20, dx: 110,  dy: -158, rot: 320,  delay: 64, color: '#06b6d4' },
        { id: 21, dx: -34,  dy: -168, rot: -40,  delay: 38, color: '#fb923c' },
        { id: 22, dx: 36,   dy: -170, rot: 50,   delay: 26, color: '#84cc16' },
      ],

      get commitItems() {
        const items = [];
        this.rows.forEach(row => {
          const commits = this.commitList(row);
          commits.forEach((commit, index) => {
            items.push({
              row,
              commit,
              commitIndex: index,
              position: index + 1,
              total: commits.length,
            });
          });
        });
        return items.sort((a, b) => String(b.commit.date || '').localeCompare(String(a.commit.date || '')));
      },

      get commitStacks() {
        return this.rows
          .filter(row => this.commitList(row).length > 0)
          .map(row => {
            const commits = this.commitList(row);
            return {
              row,
              commit: commits[0],
              commitIndex: 0,
              position: 1,
              total: commits.length,
              sortDate: String((commits[commits.length - 1] && commits[commits.length - 1].date) || (commits[0] && commits[0].date) || ''),
            };
          })
          .sort((a, b) => String(b.sortDate || '').localeCompare(String(a.sortDate || '')));
      },

      get dirtyRows() {
        return this.rows
          .filter(row => row.is_dirty)
          .sort((a, b) => {
            const ac = this.commitList(a).length;
            const bc = this.commitList(b).length;
            if (ac !== bc) return bc - ac;
            return (a.session_name || '').localeCompare(b.session_name || '');
          });
      },

      get uncommittedChangesCount() {
        return this.rows.filter(row => row.is_dirty).length;
      },

      // ── PRs view ─────────────────────────────────────────────────
      // One entry per row that has linked PRs; rows with pending
      // commits but no fetched PR state surface separately so the
      // operator can pull their PR status on demand.
      get prStacks() {
        return this.rows
          .filter(row => this.rowPrs(row).length > 0)
          .map(row => ({ row, prs: this.rowPrs(row) }))
          .sort((a, b) => (b.prs.length - a.prs.length)
            || (a.row.session_name || '').localeCompare(b.row.session_name || ''));
      },

      // Snapshot state helper: discovery (auto-jwbgb) writes
      // state="unavailable" reason="no_host_token" for repos the host
      // has no GitHub token for; the cards render a quiet note off it.
      sourceControlUnavailable(row) {
        const sc = row && row.source_control;
        return !!(sc && sc.state === 'unavailable');
      },

      get selectedOrgIdentity() {
        return this.orgs.find(o => o.slug === this.selectedOrg) || null;
      },

      rowKey(row) {
        if (!row) return '';
        return (row.session_name || '') + '/' + (row.repo_name || '');
      },

      commitKey(item) {
        if (!item || !item.commit) return '';
        return this.rowKey(item.row) + '/' + (item.commit.sha || '');
      },

      mergeKey(item) {
        return this.commitKey(item);
      },

      commitList(row) {
        return (row && row.commits) || [];
      },

      dirtyFiles(row) {
        return (row && row.dirty_files) || [];
      },

      // The list payload ships only a 3-entry preview of dirty_files plus an
      // explicit dirty_count. Trust the count when present; fall back to the
      // array length for older payloads that predate the count field.
      dirtyCount(row) {
        if (row && typeof row.dirty_count === 'number') return row.dirty_count;
        return ((row && row.dirty_files) || []).length;
      },

      shortSha(sha) {
        return _shortSha(sha);
      },

      rowOrg(row) {
        // Server-resolved org identity (session → workspace → org
        // cascade); the repo_name fallback covers rows from before the
        // field existed.
        const org = row && row.org;
        if (org && org.slug) {
          return {
            name: org.name || org.slug,
            initial: org.initial || '?',
            color: org.color || '#64748b',
          };
        }
        const repo = (row && row.repo_name) || '';
        if (repo === 'autonomy') {
          return { name: 'Autonomy', initial: 'A', color: '#6366f1' };
        }
        if (repo === 'enterprise' || repo === 'enterprise_ng') {
          return { name: 'Anchore', initial: 'A', color: '#2D7DD2' };
        }
        const initial = repo ? repo.charAt(0).toUpperCase() : '?';
        return { name: repo || 'Unknown', initial, color: '#64748b' };
      },

      // ── org scoping ──────────────────────────────────────────────
      async loadOrgs() {
        this.orgsLoading = true;
        try {
          const resp = await fetch('/api/worktrees/orgs');
          this.orgs = await _jsonOrError(resp) || [];
          if (this.selectedOrg && !this.orgs.some(o => o.slug === this.selectedOrg)) {
            this.selectedOrg = '';
          }
          // "Choose an org" only means something when there is a choice:
          // with exactly one org, auto-select it instead of showing a
          // one-button picker.
          if (!this.selectedOrg && this.orgs.length === 1) {
            this.selectedOrg = this.orgs[0].slug;
            try { localStorage.setItem('worktrees.org', this.selectedOrg); } catch (e) { /* private mode */ }
          }
        } catch (err) {
          this.error = err.message || String(err);
        } finally {
          this.orgsLoading = false;
        }
      },

      setOrg(slug) {
        if (!slug || slug === '__none__') return;
        this.selectedOrg = slug;
        try { localStorage.setItem('worktrees.org', slug); } catch (e) { /* private mode */ }
        this.rows = [];
        this.loading = true;
        this.refresh(false);
      },

      _restoreOrg() {
        try {
          this.selectedOrg = localStorage.getItem('worktrees.org') || '';
        } catch (e) {
          this.selectedOrg = '';
        }
      },

      // ── source_control / autonomy/github capability bridge ────────
      // Backend exposes review state under row.source_control.reviews
      // (plural — one entry per binding for stacked PRs; legacy
      // singular ``review`` is read as a fallback). rowPrs() adapts
      // each entry into the flatter ``pr`` shape the settled design
      // template binds against. rowPr() returns the first one for
      // back-compat with single-PR call sites.

      /**
       * @param {ReviewPayloadV1} review
       * @param {string} mode
       * @returns {object}
       */
      _adaptReview(review, mode) {
        const checks = (review.checks || []).map(c => ({
          ...c,
          // Cache stores no ``icon`` — derive it from the label so the
          // disc renders without a server-side dependency.
          icon: c.icon || this._iconFromLabel(c.label),
        }));
        const aggregate = review.aggregate_state
          || (checks.some(c => c.status === 'fail') ? 'yellow' : 'green');
        return {
          number: review.number,
          review_id: review.review_id || (review.number != null ? String(review.number) : ''),
          node_id: review.node_id || '',
          url: review.url,
          title: review.title,
          body: review.body,
          state: aggregate,
          head_sha: review.head_sha,
          base_sha: review.base_sha,
          commit_shas: Array.isArray(review.commit_shas) ? review.commit_shas.slice() : [],
          running: !!review.running,
          stale: !!review.stale,
          watch_active: mode !== 'silent',
          pr_checks: checks,
        };
      },

      /**
       * Derive a 1–2 char glyph from a check label. Mirrors the Python
       * ``_icon_from_label`` so cache rows (which never carry ``icon``)
       * still render the right disc text. Path-prefixed labels keep
       * only the trailing segment; alphas of the first one or two
       * tokens form the glyph.
       * @param {string} label
       * @returns {string}
       */
      _iconFromLabel(label) {
        let text = (label || '').trim();
        if (!text) return '?';
        for (const sep of ['/', ':']) {
          const idx = text.lastIndexOf(sep);
          if (idx >= 0) text = text.slice(idx + 1);
        }
        text = text.trim();
        if (!text) return '?';
        const parts = text.replace(/_/g, ' ').replace(/-/g, ' ')
          .split(/\s+/).filter(Boolean);
        if (!parts.length) return '?';
        const firstAlpha = (s) => {
          for (const ch of s) if (/[A-Za-z]/.test(ch)) return ch;
          return '';
        };
        const first = firstAlpha(parts[0]);
        const second = parts.length >= 2 ? firstAlpha(parts[1]) : '';
        const glyph = (first + second).toUpperCase();
        return glyph.slice(0, 2) || '?';
      },

      /**
       * @param {{source_control?: {reviews?: ReviewPayloadV1[], review?: ReviewPayloadV1}} | null} row
       * @returns {object[]}
       */
      rowPrs(row) {
        if (!row || !row.source_control) return [];
        const sc = row.source_control;
        let reviews = Array.isArray(sc.reviews) ? sc.reviews.slice() : [];
        if (!reviews.length && sc.review) reviews = [sc.review];
        if (!reviews.length) return [];
        const mode = this.rowNagMode(row);
        return reviews
          .filter(r => r != null)
          .map(r => this._adaptReview(r, mode));
      },

      /**
       * Adapt a worktree row's first review for back-compat call sites.
       * @param {{source_control?: {reviews?: ReviewPayloadV1[], review?: ReviewPayloadV1}} | null} row
       * @returns {object | null}
       */
      rowPr(row) {
        const prs = this.rowPrs(row);
        return prs.length ? prs[0] : null;
      },

      hasStackedPrs(row) {
        return this.rowPrs(row).length > 1;
      },

      // Card badge shows one PR — the bottom of the stack, the one
      // Review opens first — with any extra stack depth folded in as a
      // dimmed "+N" (design 255aeae1 v5). The full stack stays
      // navigable in the review overlay and the PRs view.
      rowPrBadgeExtra(row) {
        const extra = this.rowPrs(row).length - 1;
        return extra > 0 ? '+' + extra : '';
      },

      stackedCardCountLabel(row, total) {
        const prCount = this.rowPrs(row).length;
        if (prCount <= 1) return 'commit 1 of ' + total;
        return prCount + ' PRs · ' + total + ' commits';
      },

      stackedCardSummary(row) {
        const prCount = this.rowPrs(row).length;
        const commitCount = this.commitList(row).length;
        const prLabel = prCount === 1 ? 'PR' : 'PRs';
        const commitLabel = commitCount === 1 ? 'commit' : 'commits';
        return prCount + ' ' + prLabel + ' stacked across ' + commitCount + ' ' + commitLabel;
      },

      commitStatsSummary(commit) {
        const stats = (commit && commit.stats) || {};
        const files = Number.isFinite(stats.files)
          ? stats.files
          : (((commit && commit.files) || []).length);
        const additions = Number.isFinite(stats.additions) ? stats.additions : 0;
        const deletions = Number.isFinite(stats.deletions) ? stats.deletions : 0;
        const fileLabel = files === 1 ? 'file' : 'files';
        return files + ' ' + fileLabel + ' +' + additions + ' -' + deletions;
      },

      isMergeCommit(commit) {
        const subject = ((commit && commit.subject) || '').trim();
        return /^merge(\b|:)/i.test(subject);
      },

      mergeEntryBadge(entry) {
        const count = Array.isArray(entry && entry.commits) ? entry.commits.length : 0;
        return count > 1 ? (count + 'x merge') : 'merge';
      },

      mergeEntrySummary(entry) {
        const commits = Array.isArray(entry && entry.commits) ? entry.commits : [];
        const count = commits.length || 1;
        let files = 0;
        let additions = 0;
        let deletions = 0;
        commits.forEach((part) => {
          const stats = (part && part.commit && part.commit.stats) || {};
          files += Number.isFinite(stats.files)
            ? stats.files
            : ((((part && part.commit && part.commit.files) || []).length));
          additions += Number.isFinite(stats.additions) ? stats.additions : 0;
          deletions += Number.isFinite(stats.deletions) ? stats.deletions : 0;
        });
        const mergeLabel = count === 1 ? 'merge commit' : (count + ' merge commits');
        const fileLabel = files === 1 ? 'file' : 'files';
        return mergeLabel + ' · ' + files + ' ' + fileLabel + ' +' + additions + ' -' + deletions;
      },

      rowReviewGroups(row) {
        const commits = this.commitList(row);
        const prs = this.rowPrs(row);
        if (!prs.length) return [];

        const indexBySha = new Map();
        commits.forEach((commit, index) => {
          if (commit && commit.sha) indexBySha.set(commit.sha, index);
        });

        const ordered = prs
          .map((pr, originalIndex) => {
            const explicitShas = Array.isArray(pr.commit_shas) ? pr.commit_shas : [];
            const explicitIndices = explicitShas
              .map((sha) => indexBySha.get(sha))
              .filter((index) => Number.isInteger(index))
              .sort((a, b) => a - b);
            const headIndex = Number.isInteger(indexBySha.get(pr.head_sha))
              ? indexBySha.get(pr.head_sha)
              : -1;
            const baseIndex = Number.isInteger(indexBySha.get(pr.base_sha))
              ? indexBySha.get(pr.base_sha)
              : -1;
            const score = explicitIndices.length
              ? explicitIndices[explicitIndices.length - 1]
              : headIndex;
            return {
              pr,
              originalIndex,
              explicitIndices,
              headIndex,
              baseIndex,
              score,
            };
          })
          .sort((a, b) => {
            if (a.score < 0 && b.score < 0) return a.originalIndex - b.originalIndex;
            if (a.score < 0) return 1;
            if (b.score < 0) return -1;
            if (a.score !== b.score) return a.score - b.score;
            return a.originalIndex - b.originalIndex;
          });

        const claimed = new Set();
        let lastClaimed = -1;
        const groups = ordered.map((entry) => {
          let indices = [];
          if (entry.explicitIndices.length) {
            indices = entry.explicitIndices.filter((index) => !claimed.has(index));
          } else if (entry.headIndex >= 0) {
            const start = Math.max(
              lastClaimed + 1,
              entry.baseIndex >= 0 ? entry.baseIndex + 1 : lastClaimed + 1,
            );
            if (entry.headIndex >= start) {
              for (let index = start; index <= entry.headIndex; index += 1) {
                if (!claimed.has(index)) indices.push(index);
              }
            }
          }
          indices.forEach((index) => claimed.add(index));
          if (indices.length) lastClaimed = Math.max(lastClaimed, indices[indices.length - 1]);
          return {
            key: this.prIdentity(entry.pr) || ('pr-' + entry.originalIndex),
            pr: entry.pr,
            label: '',
            commits: indices.map((index) => ({
              commit: commits[index],
              index,
            })),
          };
        });

        const unlinked = commits
          .map((commit, index) => ({ commit, index }))
          .filter(({ index }) => !claimed.has(index));
        if (unlinked.length) {
          groups.push({
            key: 'unlinked',
            pr: null,
            label: 'Unlinked commits',
            commits: unlinked,
          });
        }
        return groups;
      },

      groupCardEntries(row, group) {
        const commits = Array.isArray(group && group.commits) ? group.commits : [];
        if (!this.hasStackedPrs(row)) {
          return commits.map((entry) => ({
            kind: 'commit',
            key: 'commit:' + (entry.commit && entry.commit.sha),
            commit: entry.commit,
            index: entry.index,
            commits: [entry],
          }));
        }

        const entries = [];
        let mergeCluster = [];
        const flushMergeCluster = () => {
          if (!mergeCluster.length) return;
          entries.push({
            kind: 'merge',
            key: 'merge:' + mergeCluster.map((entry) => entry.commit.sha).join(','),
            commit: mergeCluster[0].commit,
            index: mergeCluster[0].index,
            commits: mergeCluster.slice(),
          });
          mergeCluster = [];
        };

        commits.forEach((entry) => {
          if (this.isMergeCommit(entry.commit)) {
            mergeCluster.push(entry);
            return;
          }
          flushMergeCluster();
          entries.push({
            kind: 'commit',
            key: 'commit:' + (entry.commit && entry.commit.sha),
            commit: entry.commit,
            index: entry.index,
            commits: [entry],
          });
        });
        flushMergeCluster();
        return entries;
      },

      prIdentity(pr) {
        if (!pr) return '';
        if (pr.review_id) return 'review:' + pr.review_id;
        if (pr.number != null) return 'number:' + String(pr.number);
        if (pr.head_sha) return 'head:' + pr.head_sha;
        return '';
      },

      matchingRowPr(row, pr) {
        const prs = this.rowPrs(row);
        if (!prs.length) return null;
        const identity = this.prIdentity(pr);
        if (!identity) return prs[0];
        return prs.find(candidate => this.prIdentity(candidate) === identity) || null;
      },

      prIsFlashing(pr) {
        return !!pr && !!pr.watch_active && !!pr.running;
      },

      prBadgeClass(pr) {
        if (!pr) return 'border-white/10 bg-white/[0.03] text-slate-300';
        if (pr.state === 'green') return 'border-emerald-300/20 bg-emerald-300/10 text-emerald-100';
        return 'border-amber-300/20 bg-amber-300/10 text-amber-100';
      },

      prDotClass(pr) {
        if (!pr) return 'bg-slate-400';
        const tone = pr.state === 'green' ? 'bg-emerald-300' : 'bg-amber-200';
        return tone + (this.prIsFlashing(pr) ? ' animate-pulse' : '');
      },

      // Per-PR check list for the on-card navigator. Each entry is a
      // {@link CheckEntryV1} from the capability's
      // normalize_review_payload (settled design 3435e03f, lines 215-226).
      // Now takes an explicit ``pr`` so stacked PRs render one row per PR
      // with its own checks; back-compat overload (one arg) returns the
      // first PR's checks for legacy call sites.
      /**
       * @param {object | null} row
       * @param {object | null} [pr]
       * @returns {CheckEntryV1[]}
       */
      rowPrChecks(row, pr) {
        const target = pr || this.rowPr(row);
        return (target && target.pr_checks) || [];
      },

      // ── Rich check-tooltip popover ───────────────────────────────────
      // Replaces the native ``title`` attribute with an anchor-positioned
      // popover (settled design 3435e03f, lines 779-788). Lifted from
      // the design's helpers; one piece of mutable state on the
      // worktreesPage component.
      checkTooltip: {
        visible: false,
        text: '',
        detail: '',
        x: 0,
        y: 0,
        key: '',
      },

      /**
       * @param {CheckEntryV1['status'] | string | null | undefined} status
       * @returns {string}
       */
      describeCheckStatus(status) {
        if (status === 'pass') return 'passing';
        if (status === 'running') return 'running';
        if (status === 'pending') return 'pending';
        if (status === 'fail') return 'failing';
        return status || 'unknown';
      },

      /** @param {CheckEntryV1 | null | undefined} check */
      checkTooltipKey(check) {
        if (!check) return '';
        return [check.id, check.icon, check.label, check.status, check.detail].join('|');
      },

      /** @param {CheckEntryV1 | null | undefined} check */
      checkTooltipText(check) {
        if (!check) return '';
        return (check.label || 'Check') + ' — ' + this.describeCheckStatus(check.status);
      },

      /** @param {CheckEntryV1 | null | undefined} check */
      checkTooltipDetail(check) {
        return (check && check.detail) || '';
      },

      tooltipAnchorPoint(event) {
        const target = event && event.currentTarget;
        if (target && typeof target.getBoundingClientRect === 'function') {
          const rect = target.getBoundingClientRect();
          return {
            x: Math.min(window.innerWidth - 16, Math.max(16, rect.left + rect.width / 2)),
            y: Math.max(16, rect.top),
          };
        }
        return {
          x: Math.min(window.innerWidth - 16, Math.max(16, (event && event.clientX) || window.innerWidth / 2)),
          y: Math.max(16, (event && event.clientY) || window.innerHeight / 2),
        };
      },

      showCheckTooltip(event, check) {
        const point = this.tooltipAnchorPoint(event || {});
        this.checkTooltip.visible = true;
        this.checkTooltip.text = this.checkTooltipText(check);
        this.checkTooltip.detail = this.checkTooltipDetail(check);
        this.checkTooltip.x = point.x;
        this.checkTooltip.y = point.y;
        this.checkTooltip.key = this.checkTooltipKey(check);
      },

      hideCheckTooltip() {
        this.checkTooltip.visible = false;
        this.checkTooltip.detail = '';
        this.checkTooltip.key = '';
      },

      toggleCheckTooltip(event, check) {
        const key = this.checkTooltipKey(check);
        if (this.checkTooltip.visible && this.checkTooltip.key === key) {
          this.hideCheckTooltip();
          return;
        }
        this.showCheckTooltip(event, check);
      },

      // ── Nag controls (Silent / Nag All Changes / Nag When Done) ─────
      // Backend mode strings (worktree_monitor.py NAG_*) are
      // 'silent' / 'nag_all' / 'nag_done'. UI labels match auto-r098a.
      rowNagMode(row) {
        const watch = row && row.source_control && row.source_control.watch;
        return (watch && watch.mode) || 'silent';
      },

      nagButtonClass(row, mode) {
        const active = this.rowNagMode(row) === mode;
        return active
          ? 'border-white/10 bg-white/10 text-white'
          : 'text-slate-400 hover:border-white/10 hover:bg-white/[0.05] hover:text-slate-200';
      },

      async setNagMode(row, mode) {
        if (!row) return;
        // Optimistic update — write the new mode locally so the click
        // feels instant; revert on error.
        const prev = this.rowNagMode(row);
        if (!row.source_control) row.source_control = {state: 'unavailable', review: null, watch: {mode}};
        if (!row.source_control.watch) row.source_control.watch = {mode};
        row.source_control.watch.mode = mode;
        try {
          const url = '/api/worktrees/'
            + encodeURIComponent(row.session_name) + '/'
            + encodeURIComponent(row.repo_name) + '/watch';
          const resp = await fetch(url, {
            method: 'PUT',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({mode}),
          });
          if (!resp.ok) throw new Error('HTTP ' + resp.status);
        } catch (err) {
          row.source_control.watch.mode = prev;
          _toast('Failed to update nag mode: ' + (err.message || err));
        }
      },

      // Per-commit checks. gh's statusCheckRollup is keyed to the PR's
      // head SHA, not individual commits, so the v1 capability surface
      // doesn't expose per-commit checks. Return [] until that lands.
      reviewCommitChecks(_commit) {
        return [];
      },

      // Disc styling for navigator check icons. Lifted verbatim from
      // the settled design's checkIconClass helper.
      checkIconClass(status) {
        if (status === 'pass') return 'border-emerald-300/20 bg-emerald-300/12 text-emerald-100';
        if (status === 'running') return 'border-amber-300/20 bg-amber-300/12 text-amber-100';
        if (status === 'pending') return 'border-white/10 bg-white/[0.03] text-slate-300';
        if (status === 'fail') return 'border-rose-300/20 bg-rose-300/12 text-rose-100';
        return 'border-white/10 bg-white/[0.03] text-slate-300';
      },

      // Compact "X commits" label used by the navigator card header.
      commitCountLabel(row) {
        const n = this.commitList(row).length;
        if (n === 0) return 'no commits';
        if (n === 1) return '1 commit';
        return n + ' commits';
      },

      // Navigator click handlers. Until the PR-mode review overlay lands
      // (separate chunk), all three route to the existing commit-review
      // path: PR row falls through to commit 0, individual rows pick the
      // chosen commit. The bindings are faithful to the settled design so
      // the PR-mode overlay can replace these without template churn.
      _itemForCommit(row, idx) {
        return this.commitAt(row, idx);
      },

      async openReviewCommit(row, idx) {
        const item = this._itemForCommit(row, idx);
        if (item) await this.selectCommit(item);
      },

      // PR-mode review overlay (auto-r098a). Fetches the integrated
      // ``merge-base..HEAD`` diff via /pr-diff and slots it into
      // ``selectedCommit`` with ``prMode: true`` so the existing
      // overlay renders the PR title/body + integrated patch with
      // tiny conditional tweaks (no separate template block).
      //
      // When ``pr`` is supplied (per-PR navigator click for stacked
      // PRs), the fetch carries ``?review_id=X`` so the server scopes
      // the diff to that single PR's commit range via the binding's
      // ``base_sha``. Default callers (single-PR badge click) get the
      // first PR.
      async openReviewPr(row, pr) {
        if (!pr) pr = this.rowPr(row);
        if (!pr) {
          await this.openReviewCommit(row, 0);
          return;
        }

        this.selectedDirtyRow = null;
        this.confirmDiscardRow = null;
        this.detailLoading = true;
        this.mergeState = 'idle';
        this.mergeBurstActive = false;
        this.reviewTitlePinned = false;
        this.showDiff = false;

        // Synthetic selectedCommit: the PR is treated as one big virtual
        // "commit" so the existing overlay's diff machinery just works.
        // ``prMode: true`` is the marker the template guards on; ``sha``
        // is prefixed so it can never collide with a real commit key.
        const requestKey = '_pr_/' + (pr.head_sha || pr.number || '') + '/' + Date.now();
        this.selectedCommit = {
          row,
          commit: {
            sha: requestKey,
            short_sha: 'PR',
            subject: pr.title || ('PR #' + (pr.number || '')),
            body: pr.body || '',
            author: '',
            date: '',
            files: [],
            stats: {files: 0, additions: 0, deletions: 0},
            patch: '',
            stale: false,
            stale_reason: '',
          },
          commitIndex: -1,
          position: 0,
          total: 0,
          patchFiles: {},
          prMode: true,
          pr,
        };
        this.queueCommitStickyOffsets();
        this.queueBranchLayouts();
        this.queuePathMeasurements();
        this.queueReviewHeaderState();

        try {
          const reviewParam = pr.review_id || (pr.number != null ? String(pr.number) : '');
          const url = '/api/worktrees/' + encodeURIComponent(row.session_name) + '/'
            + encodeURIComponent(row.repo_name) + '/pr-diff'
            + (reviewParam ? ('?review_id=' + encodeURIComponent(reviewParam)) : '');
          const resp = await fetch(url);
          const detail = await _jsonOrError(resp);
          // Bail if user navigated away while the fetch was in flight.
          if (!this.selectedCommit || this.selectedCommit.commit.sha !== requestKey) return;
          const files = detail.files || [];
          this.selectedCommit = {
            ...this.selectedCommit,
            commit: {
              ...this.selectedCommit.commit,
              files,
              patch: detail.patch || '',
              stale: !!detail.stale,
              stale_reason: detail.reason || '',
              stats: {
                files: files.length,
                additions: files.reduce((s, f) => s + (f.additions || 0), 0),
                deletions: files.reduce((s, f) => s + (f.deletions || 0), 0),
              },
            },
            patchFiles: _patchIndex(detail.patch || ''),
          };
          this.queueCommitStickyOffsets();
          this.queueBranchLayouts();
          this.queuePathMeasurements();
          this.queueReviewHeaderState();
        } catch (err) {
          _toast('PR diff failed: ' + (err.message || String(err)), 'error');
        } finally {
          if (this.selectedCommit && this.selectedCommit.commit.sha === requestKey) {
            this.detailLoading = false;
          }
        }
      },

      async openReviewDefault(row) {
        const prs = this.rowPrs(row);
        if (prs.length) {
          await this.openReviewPr(row, prs[0]);
        } else {
          await this.openReviewCommit(row, 0);
        }
      },

      isPrReview() {
        return !!(this.selectedCommit && this.selectedCommit.prMode);
      },

      repoName(row) {
        return (row && row.repo_name) || 'unknown';
      },

      changesCompanionCommitLabel(row) {
        const count = this.commitList(row).length;
        if (!count) return 'changes only';
        return count === 1 ? '1 commit also present' : count + ' commits also present';
      },

      statusLabel(row) {
        if (row.session_live) return 'LIVE';
        if (row.is_dirty || row.commits_ahead > 0 || this.commitList(row).length > 0) return 'ORPHANED';
        return 'DEAD-CLEAN';
      },

      statusClass(row) {
        const status = this.statusLabel(row);
        if (status === 'LIVE') return 'bg-emerald-300/15 text-emerald-200';
        if (status === 'ORPHANED') return 'bg-amber-300/15 text-amber-200';
        return 'bg-slate-700 text-slate-300';
      },

      displayStatus(status) {
        if (status === '??') return 'U';
        return status || '';
      },

      statusTitle(status) {
        if (status === '??') return 'Untracked';
        if (status === 'M') return 'Modified';
        if (status === 'A') return 'Added';
        if (status === 'D') return 'Deleted';
        return status || '';
      },

      fitPath(path, el) {
        void this.pathMeasureTick;
        if (!path || !el) return path || '';
        const width = Math.floor(el.getBoundingClientRect().width);
        if (!width) return path;
        return _fitPathToWidth(path, width, el);
      },

      queuePathMeasurements() {
        this.$nextTick(() => {
          this.pathMeasureTick += 1;
        });
      },

      sourceBranch(row) {
        return (row && row.branch) || 'detached';
      },

      targetBranch(row) {
        if (!row) return 'main';
        if (row.target_branch) return row.target_branch;
        const source = this.sourceBranch(row);
        if (source === 'session/' + row.session_name) return 'main';
        return source;
      },

      cloneStale(row) {
        return !!(row && row.clone_stale);
      },

      canDiscardDirtyRow(row) {
        return !!row && !row.session_live;
      },

      supportsDashboardMerge(row) {
        return !!row && row.repo_name === 'autonomy';
      },

      canMergeCommit(item) {
        return !!item &&
          !!item.commit &&
          this.supportsDashboardMerge(item.row) &&
          !this.cloneStale(item.row) &&
          item.position === 1 &&
          !!item.row.ff_eligible;
      },

      canRequestRebase(item) {
        return !!item &&
          this.supportsDashboardMerge(item.row) &&
          !this.cloneStale(item.row) &&
          item.position === 1 &&
          !!item.row.rebase_required &&
          !!item.row.session_live;
      },

      canCherryPick(item) {
        // Cherry-pick is the dead-session-friendly path: when FF isn't
        // possible (master moved past the worktree's fork point) but the
        // single ahead commit would auto-merge cleanly, surface an enabled
        // "Cherry Pick to <branch>" button. No session_live gate — the
        // whole point is to land orphaned commits from dead sessions.
        return !!item &&
          this.supportsDashboardMerge(item.row) &&
          !this.cloneStale(item.row) &&
          item.position === 1 &&
          !item.row.ff_eligible &&
          !!item.row.cherry_pick_eligible;
      },

      mergeDisabledReason(item) {
        if (!item || !item.commit) return 'No commit selected';
        if (!this.supportsDashboardMerge(item.row)) return 'Review only for this repo';
        if (this.cloneStale(item.row)) return 'Sync Worktree to Latest before merging';
        if (item.position !== 1) return 'Merge earlier commit first';
        if (item.row.rebase_required && item.row.is_dirty) {
          return 'Parent has advanced; stash or commit uncommitted changes before rebasing';
        }
        if (item.row.rebase_required) return 'Parent has advanced; rebase required before merge';
        return '';
      },

      isSyncingBase(row) {
        return !!(row && this.syncingBase[this.rowKey(row)]);
      },

      mergeCommitLabel(item) {
        if (!item || !item.commit) return 'No commit selected';
        if (!this.supportsDashboardMerge(item.row)) return 'Review only for this repo';
        if (item.position !== 1) return 'Merge earlier commit first';
        return 'Merge ' + (item.commit.short_sha || this.shortSha(item.commit.sha)) + ' into ' + this.targetBranch(item.row);
      },

      isPoofingRow(row) {
        return !!row && this.poofingRowKey === this.rowKey(row);
      },

      isCleaningRow(row) {
        return !!(row && this.cleaning[this.rowKey(row)]);
      },

      discardPromptTitle(row) {
        if (!row) return '';
        return this.rowOrg(row).name + ' ' + row.session_name;
      },

      commitAt(row, index) {
        const commits = this.commitList(row);
        if (!commits.length) return null;
        const safeIndex = Math.max(0, Math.min(index, commits.length - 1));
        return {
          row,
          commit: commits[safeIndex],
          pr: this.prForCommitIndex(row, safeIndex),
          commitIndex: safeIndex,
          position: safeIndex + 1,
          total: commits.length,
          patchFiles: {},
        };
      },

      prForCommitIndex(row, index) {
        const groups = this.rowReviewGroups(row);
        for (const group of groups) {
          if (!group || !group.pr) continue;
          const commits = Array.isArray(group.commits) ? group.commits : [];
          if (commits.some((entry) => entry.index === index)) return group.pr;
        }
        return null;
      },

      markCherryPickedRowLanded(row) {
        if (!row) return;
        const key = this.rowKey(row);
        let changed = false;
        this.rows = this.rows.map((item) => {
          if (this.rowKey(item) !== key) return item;
          changed = true;
          return {
            ...item,
            commits: [],
            commits_ahead: 0,
            cherry_pick_eligible: false,
            cherry_pick_commit: null,
            ff_eligible: false,
            rebase_required: false,
          };
        });
        if (changed) {
          this.queueBranchLayouts();
          this.queuePathMeasurements();
        }
      },

      syncOverlayRows() {
        if (this.selectedCommit) {
          const row = this.rows.find(item => this.rowKey(item) === this.rowKey(this.selectedCommit.row));
          if (!row) {
            this.selectedCommit = null;
          } else if (this.selectedCommit.prMode) {
            const nextPr = this.matchingRowPr(row, this.selectedCommit.pr) || this.selectedCommit.pr;
            this.selectedCommit = {
              ...this.selectedCommit,
              row,
              pr: nextPr,
              commit: {
                ...this.selectedCommit.commit,
                subject: (nextPr && nextPr.title) || this.selectedCommit.commit.subject,
                body: (nextPr && nextPr.body) || this.selectedCommit.commit.body || '',
              },
            };
          } else {
            const commits = this.commitList(row);
            if (!commits.length) {
              this.selectedCommit = null;
            } else {
              const nextIndex = Math.max(0, Math.min(this.selectedCommit.commitIndex || 0, commits.length - 1));
              const nextCommit = commits[nextIndex];
              const nextPr = this.prForCommitIndex(row, nextIndex);
              const sameCommit = this.selectedCommit.commit && this.selectedCommit.commit.sha === nextCommit.sha;
              this.selectedCommit = {
                ...this.selectedCommit,
                row,
                pr: nextPr,
                commit: sameCommit
                  ? {
                    ...nextCommit,
                    patch: this.selectedCommit.commit.patch,
                    files: this.selectedCommit.commit.files || nextCommit.files,
                    body: this.selectedCommit.commit.body || nextCommit.body,
                  }
                  : nextCommit,
                commitIndex: nextIndex,
                position: nextIndex + 1,
                total: commits.length,
                patchFiles: sameCommit ? this.selectedCommit.patchFiles : {},
              };
            }
          }
        }

        if (this.selectedDirtyRow) {
          const row = this.rows.find(item => this.rowKey(item) === this.rowKey(this.selectedDirtyRow));
          if (!row || !row.is_dirty) {
            this.selectedDirtyRow = null;
          } else {
            this.selectedDirtyRow = {
              ...row,
              files: this.selectedDirtyRow.files || this.dirtyFiles(row),
              patchFiles: this.selectedDirtyRow.patchFiles || {},
            };
          }
        }

        if (this.confirmDiscardRow) {
          const row = this.rows.find(item => this.rowKey(item) === this.rowKey(this.confirmDiscardRow));
          this.confirmDiscardRow = row || null;
        }
      },

      patchLinesForFile(view, file) {
        if (!view || !view.patchFiles || !file) return [];
        return view.patchFiles[file.path] || [];
      },

      queueBranchLayouts() {
        this.$nextTick(() => {
          const root = this.$root;
          if (!root) return;
          root.querySelectorAll('[data-branch-row]').forEach((el) => {
            this.syncBranchLayout(el);
          });
        });
      },

      syncBranchLayout(el) {
        if (!el) return;
        const src = el.querySelector('[data-branch-part="src"]');
        const dst = el.querySelector('[data-branch-part="dst"]');
        const arrow = el.querySelector('[data-branch-part="arrow"]');
        if (!src || !dst) return;
        const available = el.clientWidth;
        if (!available) return;
        const forceStacked = window.matchMedia('(max-width: 639px)').matches;

        const styles = window.getComputedStyle(el);
        const gap = Number.parseFloat(styles.columnGap || styles.gap || '0') || 0;
        const totalWidth =
          src.getBoundingClientRect().width +
          dst.getBoundingClientRect().width +
          (arrow ? arrow.getBoundingClientRect().width : 0) +
          gap * (arrow ? 2 : 1);
        const inlineFits = !forceStacked && totalWidth <= (available + 1);

        el.dataset.branchLayout = inlineFits ? 'inline' : 'stacked';
        el.style.flexDirection = inlineFits ? 'row' : 'column';
        el.style.alignItems = inlineFits ? 'center' : 'flex-start';
        el.style.flexWrap = 'nowrap';
        if (arrow) {
          arrow.style.display = inlineFits ? 'inline' : 'none';
        }
      },

      updateCommitStickyOffsets() {
        const titleBar = this.$refs.commitTitleBar || this.$refs.dirtyTitleBar;
        const filesHeader = this.$refs.commitFilesHeader || this.$refs.dirtyFilesHeader;
        this.commitStickyTop = titleBar ? Math.max(0, Math.round(titleBar.getBoundingClientRect().height)) : 0;
        this.commitFileRowStickyTop = this.commitStickyTop + (filesHeader ? filesHeader.getBoundingClientRect().height : 0);
      },

      queueCommitStickyOffsets() {
        this.$nextTick(() => {
          this.updateCommitStickyOffsets();
          this.observeCommitStickyElements();
        });
      },

      queueReviewHeaderState() {
        this.$nextTick(() => {
          this.observeReviewTitleSentinel();
          this.syncReviewHeaderState();
        });
      },

      syncReviewHeaderState() {
        const scroller = this.$refs.commitDetailScroller || this.$refs.dirtyDetailScroller;
        const titleBar = this.$refs.commitTitleBar || this.$refs.dirtyTitleBar;
        if (!scroller || !titleBar) return;
        if (this._reviewTitleObserver) {
          this.updateCommitStickyOffsets();
          return;
        }
        const isMobile = window.matchMedia('(max-width: 639px)').matches;
        const enterCompactAt = titleBar.offsetTop - 1;
        const exitCompactAt = enterCompactAt - 48;
        let compact = false;
        if (isMobile) {
          compact = this.reviewTitlePinned
            ? scroller.scrollTop >= exitCompactAt
            : scroller.scrollTop >= enterCompactAt;
        }
        if (this.reviewTitlePinned !== compact) {
          this.reviewTitlePinned = compact;
          this.queueCommitStickyOffsets();
          return;
        }
        this.updateCommitStickyOffsets();
      },

      observeReviewTitleSentinel() {
        this.disconnectReviewTitleObserver();
        if (typeof window.IntersectionObserver !== 'function') return;
        const isMobile = window.matchMedia('(max-width: 639px)').matches;
        if (!isMobile) {
          this.reviewTitlePinned = false;
          return;
        }

        const scroller = this.$refs.commitDetailScroller || this.$refs.dirtyDetailScroller;
        const sentinel = this.$refs.commitTitleSentinel || this.$refs.dirtyTitleSentinel;
        if (!scroller || !sentinel) return;

        this._reviewTitleObserver = new window.IntersectionObserver((entries) => {
          const entry = entries && entries[0];
          if (!entry) return;
          const rootTop = entry.rootBounds ? entry.rootBounds.top : 0;
          const compact = !entry.isIntersecting && entry.boundingClientRect.top < rootTop;
          if (this.reviewTitlePinned !== compact) {
            this.reviewTitlePinned = compact;
            this.queueCommitStickyOffsets();
            return;
          }
          this.updateCommitStickyOffsets();
        }, {
          root: scroller,
          threshold: [0, 1],
        });
        this._reviewTitleObserver.observe(sentinel);
      },

      scheduleCommitStickyOffsetUpdate() {
        if (this._commitStickyRaf) return;
        this._commitStickyRaf = window.requestAnimationFrame(() => {
          this._commitStickyRaf = 0;
          this.updateCommitStickyOffsets();
        });
      },

      observeCommitStickyElements() {
        this.disconnectCommitStickyObserver();
        if (typeof window.ResizeObserver !== 'function') return;
        const titleBar = this.$refs.commitTitleBar || this.$refs.dirtyTitleBar;
        const filesHeader = this.$refs.commitFilesHeader || this.$refs.dirtyFilesHeader;
        if (!titleBar && !filesHeader) return;
        this._commitStickyResizeObserver = new window.ResizeObserver(() => {
          this.scheduleCommitStickyOffsetUpdate();
        });
        if (titleBar) this._commitStickyResizeObserver.observe(titleBar);
        if (filesHeader) this._commitStickyResizeObserver.observe(filesHeader);
      },

      disconnectCommitStickyObserver() {
        if (this._commitStickyResizeObserver) {
          this._commitStickyResizeObserver.disconnect();
          this._commitStickyResizeObserver = null;
        }
        if (this._commitStickyRaf) {
          window.cancelAnimationFrame(this._commitStickyRaf);
          this._commitStickyRaf = 0;
        }
      },

      disconnectReviewTitleObserver() {
        if (this._reviewTitleObserver) {
          this._reviewTitleObserver.disconnect();
          this._reviewTitleObserver = null;
        }
      },

      hasOverlayOpen() {
        return !!(this.selectedCommit || this.selectedDirtyRow || this.confirmDiscardRow || this.rebaseRequiredDialog);
      },

      async openSessionOverlay(sessionName) {
        if (!sessionName) return false;
        await this.refresh(false);
        let matches = this.rows.filter((row) => row.session_name === sessionName);
        if (!matches.length) {
          // The overlay is session-scoped, but refresh() is gated on the
          // page-level org filter — when it's unset (picker showing) or
          // pointed at a different org than this session, rows come back
          // empty and the session viewer's affordance would wrongly fall
          // back to a /worktrees navigation. Look the session up
          // unfiltered instead; the page-level rows/filter are untouched.
          try {
            const resp = await fetch('/api/worktrees');
            const allRows = _normalizeRows(await _jsonOrError(resp));
            matches = allRows.filter((row) => row.session_name === sessionName);
          } catch (_err) {
            return false;
          }
        }
        if (!matches.length) return false;
        const withPrs = matches.find((row) => this.rowPrs(row).length > 0);
        if (withPrs) {
          await this.openReviewDefault(withPrs);
          return true;
        }
        const withCommits = matches.find((row) => (this.commitList(row) || []).length > 0);
        if (withCommits) {
          await this.openReviewDefault(withCommits);
          return true;
        }
        const dirtyMatch = matches.find((row) => row.is_dirty);
        if (dirtyMatch) {
          await this.selectDirtyRow(dirtyMatch);
          return true;
        }
        return false;
      },

      canRefreshSelectedRow() {
        const row = this.selectedCommit && this.selectedCommit.row;
        return !!(row && row.session_name && row.repo_name);
      },

      async openCommitOverlay(opts) {
        const options = opts || {};
        const runId = options.runId || '';
        if (!runId) return false;

        const syntheticRow = {
          session_name: options.sessionName || '',
          repo_name: options.repoName || '',
          branch: options.branch || '',
          target_branch: options.targetBranch || '',
          session_live: !!(options.sessionName || ''),
          session_project: '',
          commits_ahead: 1,
          is_dirty: false,
          ff_eligible: false,
          rebase_required: false,
          cherry_pick_eligible: false,
          clone_stale: false,
          commits: [],
        };
        const requestKey = '_activity_/' + runId + '/' + Date.now();
        const fallbackSubject = options.subject || 'Commit diff';

        this.selectedDirtyRow = null;
        this.confirmDiscardRow = null;
        this.detailLoading = true;
        this.mergeState = 'idle';
        this.mergeBurstActive = false;
        this.reviewTitlePinned = false;
        this.showDiff = true;
        this.selectedCommit = {
          requestKey,
          row: syntheticRow,
          commit: {
            sha: requestKey,
            short_sha: '',
            subject: fallbackSubject,
            body: '',
            author: '',
            date: '',
            files: [],
            stats: { files: 0, additions: 0, deletions: 0 },
            patch: '',
            stale: false,
            stale_reason: '',
          },
          pr: null,
          commitIndex: 0,
          position: 1,
          total: 1,
          patchFiles: {},
          prMode: false,
        };
        this.queueCommitStickyOffsets();
        this.queueBranchLayouts();
        this.queuePathMeasurements();
        this.queueReviewHeaderState();

        try {
          const resp = await fetch(
            '/api/dispatch/runs/' + encodeURIComponent(runId) + '/commit-detail',
          );
          const detail = await _jsonOrError(resp);
          if (!this.selectedCommit || this.selectedCommit.requestKey !== requestKey) {
            return false;
          }
          this.selectedCommit = {
            ...this.selectedCommit,
            commit: {
              ...this.selectedCommit.commit,
              ...detail,
              files: detail.files || [],
              stats: _commitStats(detail),
            },
            patchFiles: _patchIndex(detail.patch || ''),
          };
          this.queueCommitStickyOffsets();
          this.queueBranchLayouts();
          this.queuePathMeasurements();
          this.queueReviewHeaderState();
          return true;
        } catch (_err) {
          if (this.selectedCommit && this.selectedCommit.requestKey === requestKey) {
            this.selectedCommit = null;
          }
          return false;
        } finally {
          if (this.selectedCommit && this.selectedCommit.requestKey === requestKey) {
            this.detailLoading = false;
          }
        }
      },

      syncScrollLock() {
        const locked = this.hasOverlayOpen();
        document.documentElement.style.overflow = locked ? 'hidden' : '';
        document.body.style.overflow = locked ? 'hidden' : '';
      },

      diffMarker(kind) {
        if (kind === 'add') return '+';
        if (kind === 'del') return '-';
        return ' ';
      },

      async refresh(manual, options) {
        const opts = options || {};
        if (!this.selectedOrg) {
          // No org chosen yet — nothing to fetch; the picker is showing.
          this.loading = false;
          return false;
        }
        const orgQuery = '?org=' + encodeURIComponent(this.selectedOrg);
        if (manual) this.refreshing = true;
        this.error = '';
        try {
          const resp = manual
            ? await fetch('/api/worktrees/refresh' + orgQuery, { method: 'POST' })
            : await fetch('/api/worktrees' + orgQuery);
          this.rows = _normalizeRows(await _jsonOrError(resp));
          if (manual) this.loadOrgs(); // keep dropdown counts fresh; not awaited
          this.syncOverlayRows();
          this.lastUpdated = new Date().toLocaleTimeString();
          this.queueBranchLayouts();
          this.queuePathMeasurements();
          this.queueCommitStickyOffsets();
          this.queueReviewHeaderState();
          return true;
        } catch (err) {
          const message = err.message || String(err);
          if (opts.suppressErrorToast) return false;
          this.error = message;
          // If the failure leaves the page empty (initial load, or
          // the prior data has already been cleared), the page is in
          // an unrecoverable state — escalate the toast to a full-
          // screen modal with a Refresh button rather than letting
          // an 8-second toast scroll away over a blank surface. A
          // failed manual refresh of a populated page still has
          // visible data on screen, so a regular toast is fine.
          const fatal = !this.rows || this.rows.length === 0;
          _toast(
            'Worktree refresh failed: ' + this.error,
            fatal ? 'fatal' : 'error',
          );
          return false;
        } finally {
          this.loading = false;
          this.refreshing = false;
        }
      },

      isCardRefreshing(row) {
        return !!(row && this.cardRefreshing[this.rowKey(row)]);
      },

      async _refreshRowFromServer(row) {
        const resp = await fetch(
          '/api/worktrees/' + encodeURIComponent(row.session_name) + '/'
            + encodeURIComponent(row.repo_name) + '/refresh',
          { method: 'POST' },
        );
        const updatedRaw = await _jsonOrError(resp);
        const [updated] = _normalizeRows([updatedRaw]);
        const targetKey = this.rowKey(row);
        const idx = this.rows.findIndex(r => this.rowKey(r) === targetKey);
        if (idx >= 0) {
          this.rows.splice(idx, 1, updated);
        } else {
          this.rows.push(updated);
        }
        this.lastUpdated = new Date().toLocaleTimeString();
        this.queueBranchLayouts();
        this.queuePathMeasurements();
        this.queueCommitStickyOffsets();
        this.queueReviewHeaderState();
        return updated;
      },

      async refreshRowSourceControl(row) {
        if (!row) return;
        const key = this.rowKey(row);
        if (this.cardRefreshing[key]) return;
        this.cardRefreshing[key] = true;
        try {
          await this._refreshRowFromServer(row);
          this.syncOverlayRows();
        } catch (err) {
          _toast('Per-row refresh failed: ' + (err.message || String(err)), 'error');
        } finally {
          delete this.cardRefreshing[key];
        }
      },

      // Per-row force-refresh button on the review overlay.
      // Posts to /api/worktrees/{session}/{repo}/refresh — the
      // operator-explicit force-GET path that bypasses the per-row
      // TTL + poll budget for ONE row only. Replaces the row in
      // this.rows with the server's response and re-syncs the
      // overlay so the new source_control snapshot renders
      // immediately.
      async refreshSelectedRow() {
        if (!this.selectedCommit || !this.selectedCommit.row) return;
        if (this.rowRefreshing) return;
        const row = this.selectedCommit.row;
        const prMode = !!this.selectedCommit.prMode;
        const currentPr = prMode ? this.selectedCommit.pr : null;
        this.rowRefreshing = true;
        try {
          const updated = await this._refreshRowFromServer(row);
          if (prMode) {
            const refreshedPr = this.matchingRowPr(updated, currentPr);
            if (refreshedPr) {
              await this.openReviewPr(updated, refreshedPr);
            } else {
              this.syncOverlayRows();
            }
          } else {
            this.syncOverlayRows();
          }
        } catch (err) {
          _toast('Per-row refresh failed: ' + (err.message || String(err)), 'error');
        } finally {
          this.rowRefreshing = false;
        }
      },

      async _ensureOpenpgp() {
        if (window.openpgp) return window.openpgp;
        await new Promise((resolve, reject) => {
          const el = document.createElement('script');
          el.src = '/static/vendor/openpgp-6.3.1.min.js';
          el.onload = resolve;
          el.onerror = () => reject(new Error('failed to load the signing library'));
          document.head.appendChild(el);
        });
        return window.openpgp;
      },

      // ── On-demand approvals ─────────────────────────────────────
      // Per-kind handlers for /api/approvals requests — the ONLY place kinds
      // differ on the client. Each entry renders the fetched request into
      // overlay state; the chrome and Decline are kind-agnostic (declining is
      // identical for every kind, so it lives in the shell).
      _approvalKinds: {
        vault_open: {
          open(self, r) {
            const req = r.request || {};
            const ceremony = r.ceremony;
            const setting = req.setting || {};
            const requester = req.requester || {};
            const legacyCeremony = ceremony && ceremony.v === 1 &&
              ['password', 'prf', 'both'].includes(ceremony.policy) &&
              Array.isArray(ceremony.factors) && ceremony.factors.length;
            const rootCeremony = ceremony && ceremony.v === 2 &&
              ceremony.governance && ceremony.governance.form === 'root-reachable' &&
              ceremony.anchor && ceremony.root &&
              ceremony.governance.anchor_id === ceremony.anchor.anchor_id &&
              Array.isArray(ceremony.root.methods) && ceremony.root.methods.length &&
              ceremony.root.methods.every((method) =>
                ['password', 'passkey', 'both'].includes(method));
            if ((!legacyCeremony && !rootCeremony) ||
                !setting.set_id || !setting.key || !requester.session ||
                !requester.organization ||
                !requester.workspace || req.operation !== 'read' ||
                req.release_mode !== 'delivered') {
              throw new Error('vault open request has no complete server-frozen ceremony');
            }
            const expiry = new Date(Number(req.expires_at) * 1000);
            const policyLabel = rootCeremony
              ? (req.access || ceremony.governance.display_name || 'Personal root vault')
              : (ceremony.policy === 'both'
                ? 'password + passkey' : (ceremony.policy === 'prf' ? 'passkey' : 'password'));
            const rootMethods = rootCeremony ? [...ceremony.root.methods] : [];
            const rootMethod = rootMethods.length === 1 ? rootMethods[0] : null;
            const methodNeedsPassword = (method) => method === 'password' || method === 'both';
            const methodAction = (method) => method === 'passkey'
              ? 'Use passkey & deliver' : (method === 'both'
                ? 'Verify both & deliver' : (method === 'password'
                  ? 'Open & deliver' : 'Choose an opener'));
            self.approvalBusy = false;
            const approval = {
              id: r.id, kind: r.kind, session: requester.session,
              title: 'Release secured setting',
              actionLabel: rootCeremony ? methodAction(rootMethod)
                : (ceremony.policy === 'prf'
                  ? 'Use passkey & deliver' : (ceremony.policy === 'both'
                    ? 'Verify both & deliver' : 'Open & deliver')),
              op: req.operation, target: req.target,
              bodyMarkdown: [
                'Setting: ' + setting.set_id + ' / ' + setting.key,
                'Operation: ' + req.operation,
                'Requesting organization: ' + requester.organization,
                'Requesting session: ' + requester.session,
                'Workspace: ' + requester.workspace,
                'Target: ' + req.target,
                'Delivered: ' + req.delivery,
                'Release mode: ' + req.release_mode,
                (rootCeremony ? 'Access: ' : 'Factor: ') + policyLabel,
                ...(rootCeremony ? ['Root opener: ' + (
                  rootMethod === 'both' ? 'password + passkey' :
                    (rootMethod || 'choose below')
                )] : []),
                'TTL: ' + req.ttl_seconds + ' seconds (expires ' + expiry.toLocaleTimeString() + ')',
              ].join('\n'),
              needsPassword: rootCeremony ? methodNeedsPassword(rootMethod)
                : ceremony.policy === 'password' || ceremony.policy === 'both',
              passwordLabel: rootCeremony
                ? (rootMethod === 'both'
                  ? 'Personal password (passkey also required)' : 'Personal password')
                : (ceremony.policy === 'both'
                  ? 'Vault password (passkey also required)' : 'Vault password'),
              password: '',
              vaultOpen: {
                ceremony, gathered: null, rootMethods, rootMethod,
                selectMethod(method) {
                  if (!rootMethods.includes(method)) return;
                  this.rootMethod = method;
                  approval.needsPassword = methodNeedsPassword(method);
                  approval.passwordLabel = method === 'both'
                    ? 'Personal password (passkey also required)' : 'Personal password';
                  approval.actionLabel = methodAction(method);
                  approval.bodyMarkdown = approval.bodyMarkdown.replace(
                    /^Root opener:.*$/m,
                    'Root opener: ' + (method === 'both' ? 'password + passkey' : method),
                  );
                  approval.error = '';
                  if (!approval.needsPassword) approval.password = '';
                },
              },
              awaitExecution: true,
              error: '',
            };
            self.approvalRequest = approval;
          },
          async decision(self, req) {
            const vault = await import('../ceremony/open-vault.js');
            req.vaultOpen.gathered = await vault.gatherVaultOpeners(
              req.vaultOpen.ceremony, req.password,
              { rootMethod: req.vaultOpen.rootMethod },
            );
            return { openers: req.vaultOpen.gathered.openers };
          },
          async cleanup(self, req) {
            if (req.vaultOpen && req.vaultOpen.gathered) {
              const vault = await import('../ceremony/open-vault.js');
              vault.clearVaultOpeners(req.vaultOpen.gathered);
              req.vaultOpen.gathered = null;
            }
            // JavaScript strings cannot be overwritten in place. Remove the
            // sheet's last reference after every attempt, including a failed
            // client-side armor validation.
            req.password = '';
          },
        },
        external_service_access: {
          open(self, r) {
            const access = r.staged || r.request || {};
            const requester = access.requester || {};
            const requested = access.requested_ttl_seconds;
            const allowed = new Set(['86400', '604800', '2592000', '31536000', '315360000', '']);
            const suggested = requested == null ? '' : String(requested);
            self.approvalBusy = false;
            self.approvalRequest = {
              id: r.id, kind: r.kind, session: requester.label || r.session,
              title: 'Allow external service access', actionLabel: 'Allow access',
              target: access.application || 'External service', op: 'enroll',
              bodyMarkdown: [
                access.summary || 'Allow this device to call the listed Autonomy capability.',
                '',
                'The credential is limited to the exact method and path shown below. It receives no session or organization authority.',
              ].join('\n'),
              ttl: allowed.has(suggested) ? suggested : '31536000',
              externalAccess: access,
              awaitExecution: true,
              error: '',
            };
          },
          decision(self, req) {
            return { ttl_seconds: req.ttl === '' ? null : Number(req.ttl) };
          },
        },
        mcp_peer_link: {
          async open(self, r) {
            const req = r.request || {};
            // Orgs come from the server-side ENRICH (r.orgs) so the dropdown always
            // populates; only fall back to a client fetch if that's somehow absent.
            let orgs = Array.isArray(r.orgs) ? r.orgs.filter(Boolean) : [];
            if (!orgs.length) {
              try {
                const resp = await fetch('/api/orgs');
                if (resp.ok) {
                  const d = await resp.json();
                  orgs = (d.orgs || []).map((o) => o.slug).filter(Boolean);
                }
              } catch (e) { /* typed fallback in the template */ }
            }
            const handle = req.handle || r.session || 'unknown';
            const requestedOrg = String(req.requested_org || '').trim();
            const defaultOrg = String(r.default_org || '').trim();
            const autonomyOrg = orgs.includes(requestedOrg) ? requestedOrg
              : orgs.includes(defaultOrg) ? defaultOrg
              : orgs.includes('autonomy') ? 'autonomy'
              : (orgs[0] || requestedOrg || defaultOrg);
            const requestedLevel = ['read', 'readwrite'].includes(req.requested_level)
              ? req.requested_level : 'read';
            self.approvalBusy = false;
            self.approvalRequest = {
              id: r.id, kind: r.kind, session: handle,
              title: 'Approve ChatGPT access', actionLabel: 'Approve',
              target: null,
              // Lead with the reason — it's the whole basis for the decision.
              bodyMarkdown: 'This ChatGPT chat wants to:\n\n' + (req.intent || '(no reason given)'),
              orgs,
              // Suggestions only: all three remain visible and operator-editable.
              autonomyOrg,
              level: requestedLevel,
              ttl: '86400',
              awaitExecution: true,
              error: '',
            };
          },
          decision(self, req) {
            const org = (req.autonomyOrg || '').trim();
            if (!org) throw new Error('Choose an Autonomy org to grant.');
            return { autonomy_org: org, level: req.level || 'read',
                     ttl_seconds: req.ttl === '' ? null : Number(req.ttl) };
          },
        },
        visitor_token: {
          open(self, r) {
            // The operator is deciding a person, so the panel shows one: the
            // photo they sent, their name under it, and why. Everything here
            // is what the server froze at request time -- the page never
            // renders bytes the requester supplied inline.
            const staged = r.staged || {};
            self.approvalBusy = false;
            self.approvalRequest = {
              id: r.id, kind: r.kind, session: staged.asked_by || r.session,
              title: 'Let this person in?',
              actionLabel: 'Approve',
              target: null,
              staged: staged,
              awaitExecution: true,
              error: '',
            };
          },
        },
        mcp_crosstalk: {
          open(self, r) {
            const req = r.request || {};
            const handle = req.handle || r.session || 'unknown';
            self.approvalBusy = false;
            self.approvalRequest = {
              id: r.id, kind: r.kind, session: handle,
              title: 'CrossTalk Approval Request', actionLabel: 'Approve & send',
              target: null,
              // custom crosstalk layout (no bodyMarkdown, no org/level)
              xtalk: {
                handle: handle,
                intent: req.intent || '',
                targetSession: req.target_session || 'unknown',
                targetLabel: r.target_label || '',
                message: req.message || '(message unavailable)',
              },
              ttl: '86400', // default 1 day
              awaitExecution: true,
              error: '',
            };
          },
          decision(self, req) {
            return { ttl_seconds: req.ttl === '' ? null : Number(req.ttl) };
          },
        },
        jira_write: {
          open(self, r) {
            const req = r.request || {};
            const createFields = req.op === 'create'
              ? { ...(req.fields || {}) }
              : null;
            let createDescription = '';
            if (createFields && typeof createFields.description === 'string') {
              createDescription = createFields.description;
              delete createFields.description;
            }
            const storyPointsValue = req.value === null || req.value === undefined ||
              String(req.value).trim() === '' ? '?' : String(req.value).trim();
            const storyPointsUnit = Number(storyPointsValue) === 1
              ? 'story point' : 'story points';
            const storyPointsLabel = storyPointsValue + ' ' + storyPointsUnit;
            const ops = {
              comment: { title: 'Jira comment', action: 'Post comment' },
              set_field: {
                title: 'Jira field update',
                action: 'Set ' + (req.field_name || req.field_id || 'field'),
              },
              create: { title: 'New Jira ticket', action: 'Create ticket' },
              attach: { title: 'Jira attachment', action: 'Attach file' },
              transition: {
                title: 'Jira transition',
                action: 'Transition to ' + (req.transition || '?'),
              },
              change_type: {
                title: 'Jira issue-type change',
                action: 'Change type to ' + (req.issue_type || '?'),
              },
              set_story_points: {
                title: 'Set ' + storyPointsLabel,
                action: 'Set ' + storyPointsLabel,
              },
            };
            const op = ops[req.op] || { title: 'Jira write', action: 'Approve' };
            const attachNote = req.op === 'attach'
              ? req.filename + ' (' + ((req.size || 0) / 1024).toFixed(1) + ' KB, ' +
                (req.mime_type || 'unknown type') + ')'
              : '';
            const transitionFieldLines = Object.entries(req.fields || {})
              .map(([k, v]) => '  ' + k + ': ' + v).join('\n');
            const transitionNote = req.op === 'transition'
              ? 'Transition ' + (req.key || '?') + ' → ' + (req.transition || '?') +
                (transitionFieldLines
                  ? '\n\nFields set with the transition:\n' + transitionFieldLines : '')
              : '';
            const changeTypeNote = req.op === 'change_type'
              ? 'Change ' + (req.key || '?') + ' to issue type ' + (req.issue_type || '?')
              : '';
            const storyPointsNote = req.op === 'set_story_points'
              ? 'Story Points\n\nCurrent: ' +
                (req.previous_value === null || req.previous_value === undefined
                  ? 'Unestimated' : req.previous_value) +
                '\nNew: ' + storyPointsLabel
              : '';
            self.approvalRequest = {
              id: r.id, kind: r.kind, session: r.session,
              title: op.title, actionLabel: op.action, op: req.op,
              target: req.key ||
                ((req.fields || {}).project ? (req.fields.project.key || '') : ''),
              bodyMarkdown:
                req.body_markdown || createDescription || attachNote ||
                transitionNote || changeTypeNote || storyPointsNote,
              fields: createFields,
            };
            if (req.op === 'transition' && req.key) {
              // Enrich with TRUSTED context so the operator sees what they
              // are approving: summary + current status from the broker's
              // read routes (host-side Jira reads — the requesting agent
              // cannot spoof them), and the transition's real destination
              // status (the workflow name and the status can differ).
              const org = encodeURIComponent(req.org || '');
              Promise.all([
                fetch('/api/jira/issue/' + encodeURIComponent(req.key) + '?org=' + org)
                  .then((resp) => resp.json()).catch(() => null),
                fetch('/api/jira/transitions/' + encodeURIComponent(req.key) + '?org=' + org)
                  .then((resp) => resp.json()).catch(() => null),
              ]).then(([ticket, tr]) => {
                const ar = self.approvalRequest;
                if (!ar || ar.id !== r.id) return;   // overlay changed meanwhile
                const want = (req.transition || '').toLowerCase();
                const match = ((tr && tr.transitions) || []).find((t) =>
                  (t.name || '').toLowerCase() === want ||
                  (t.to_status || '').toLowerCase() === want);
                const lines = [];
                if (ticket && !ticket.error && ticket.summary) {
                  lines.push(req.key + ' — ' + ticket.summary);
                }
                const from = (ticket && !ticket.error && ticket.status) || '?';
                const to = (match && match.to_status) || req.transition || '?';
                const via = match && match.name && match.name !== to
                  ? ' (via ‘' + match.name + '’)' : '';
                lines.push('Status: ' + from + ' → ' + to + via);
                if (transitionFieldLines) {
                  lines.push('', 'Fields set with the transition:', transitionFieldLines);
                }
                ar.bodyMarkdown = lines.join('\n');
              });
            }
            if (req.op === 'change_type' && req.key) {
              // Same trusted-context pattern as transitions: summary and the
              // ticket's REAL current type come from broker read routes,
              // not the requesting agent's payload.
              const org = encodeURIComponent(req.org || '');
              Promise.all([
                fetch('/api/jira/issue/' + encodeURIComponent(req.key) + '?org=' + org)
                  .then((resp) => resp.json()).catch(() => null),
                fetch('/api/jira/issue-types/' + encodeURIComponent(req.key) + '?org=' + org)
                  .then((resp) => resp.json()).catch(() => null),
              ]).then(([ticket, types]) => {
                const ar = self.approvalRequest;
                if (!ar || ar.id !== r.id) return;   // overlay changed meanwhile
                const lines = [];
                if (ticket && !ticket.error && ticket.summary) {
                  lines.push(req.key + ' — ' + ticket.summary);
                }
                const from = (types && !types.error && types.current &&
                              types.current.name) || '?';
                lines.push('Issue type: ' + from + ' → ' + (req.issue_type || '?'));
                ar.bodyMarkdown = lines.join('\n');
              });
            }
          },
        },
        // Share-link approval (spec §6.4): enrichment resolved the target
        // title from trusted local stores and staged the EXACT registry
        // request to sign; approve click-signs it with the operator session
        // key and rides the envelope on the decision. The server-side
        // executor forwards it to the registry and returns the URL.
        link_publish: {
          async open(self, r) {
            const session = window.AutonomyNetworkSession;
            if (session && typeof session.ready === 'function') await session.ready();
            const req = r.request || {};
            // The API uses snake_case; keep the client-side decision state in
            // camelCase so the approval handler can perform the
            // register-before-freeze retry.  Reset busy state when a new
            // approval arrives so a prior request cannot leave this button
            // disabled globally.
            self.approvalBusy = false;
            const registrationRequired = !!r.registration_required;
            const title = r.target_title || req.target_uuid || '?';
            const acting = r.acting_identity || {};
            const actor = r.actor_identity || {};
            const currentDuration = r.ttl == null ? '604800' : String(r.ttl);  // default 1 week when no TTL was requested
            const customDuration = r.ttl != null && !_LINK_DURATION_VALUES.has(currentDuration);
            const duration = customDuration ? 'custom' : currentDuration;
            const fixedExpiry = req.target_type === 'org:join';
            const approval = {
              id: r.id, kind: r.kind, session: r.session,
              gate2: true,
              title: 'Publish a share link', actionLabel: 'Approve & publish',
              action: 'Publish a share link',
              targetType: r.type_label || req.target_type || 'Item', target: title,
              // Who the link is prepared for, as an identity in its own
              // right rather than words appended to the target's name. The
              // color is computed here, view-side, from the same
              // deterministic hash the rest of the dashboard uses for this
              // participant — so this face matches their face everywhere
              // else. A real profile photo slots in here later.
              recipient: r.recipient
                ? {
                  participantId: r.recipient.participant_id,
                  displayName: r.recipient.display_name,
                  color: (window.Presence && window.Presence.participantColor)
                    ? window.Presence.participantColor(r.recipient.participant_id)
                    : 'hsl(220 70% 60%)',
                  initial: (r.recipient.display_name || '?').trim().charAt(0).toUpperCase(),
                  avatarUrl: r.recipient.avatar_url || null,
                }
                : null,
              service: 'auto.network', orgSlug: req.org || '',
              actingIdentity: acting, actorIdentity: actor,
              duration,
              fixedExpiry,
              fixedExpiryLabel: fixedExpiry && Number.isSafeInteger(
                r.absolute_expiry,
              )
                ? new Date(r.absolute_expiry).toLocaleString()
                : '',
              customDurationSeconds: customDuration ? r.ttl : null,
              customDurationLabel: customDuration ? _linkTtlText(r.ttl) : '',
              password: '', showPassword: false,
              allowSessionApprovals: false,
              registrationRequired,
              previewOpen: false, targetPreview: r.target_preview || null,
              blockingError: r.target_error ||
                (registrationRequired ? '' : r.binding_error) ||
              (r.binding_drift
                  ? 'This organization changed after the request was prepared. Close it and publish again.'
                  : ''),
              error: '',
              registryRequest: r.registry_request || null,
            };
            approval.allowSessionApprovals = _matchingApprovalAuthority(approval);
            self.approvalRequest = approval;
          },
          decision: (self, req) => _signLinkDecision(self, req),
        },
        link_revoke: {
          open(self, r) {
            const req = r.request || {};
            const title = r.target_title || req.token || '?';
            const lines = [
              'Revoke the share-link for ' + (r.type_label ? r.type_label + ' ' : '') +
                '“' + title + '”.',
              '',
              'Token: ' + (req.token || '?'),
            ];
            if (r.label) lines.push('Label: ' + r.label);
            if (!r.cached) lines.push('', '⚠ this token is not in the local grant cache');
            if (r.binding_error) lines.push('', '⚠ ' + r.binding_error);
            if (r.binding_drift) {
              lines.push('', '⚠ the org binding changed after this request was staged — approving will be refused; decline and re-run the revoke');
            }
            const approval = {
              id: r.id, kind: r.kind, session: r.session,
              title: 'Revoke share-link', actionLabel: 'Approve & revoke',
              op: 'revoke', target: title,
              bodyMarkdown: lines.join('\n'),
              orgSlug: req.org || '',
              orgUuid: r.org_uuid || null,
              targetType: r.target_type || null,
              password: '', showPassword: false,
              allowSessionApprovals: false,
              needsPassword: false,
              error: '',
              registryRequest: r.registry_request || null,
            };
            // A retained session matching this org signs without a password;
            // otherwise the sheet collects one (same rule as publish).
            approval.allowSessionApprovals = _matchingApprovalAuthority(approval);
            approval.needsPassword = !approval.allowSessionApprovals;
            self.approvalRequest = approval;
          },
          decision: (self, req) => _signLinkDecision(self, req),
        },
        dashboard_access: {
          open(self, r) {
            const grant = r.staged;
            if (!grant || typeof grant !== 'object') {
              throw new Error('dashboard access request has no server-frozen grant');
            }
            const expiry = Number.isSafeInteger(grant.expires_at)
              ? new Date(grant.expires_at * 1000).toLocaleString()
              : 'unknown';
            const ephemeral = typeof grant.ephemeral_pub === 'string'
              ? grant.ephemeral_pub : '';
            const fingerprint = ephemeral
              ? ephemeral.slice(0, 12) + '…' + ephemeral.slice(-12)
              : 'unavailable';
            self.approvalBusy = false;
            self.approvalRequest = {
              id: r.id, kind: r.kind, session: r.session,
              title: 'Dashboard access', actionLabel: 'Approve access',
              op: 'grant', target: 'Dashboard UI',
              bodyMarkdown: [
                'Grant temporary Dashboard UI access to ' + (grant.grantee || r.session) + '.',
                '',
                'Scope: ' + ((grant.scope || []).join(', ') || 'none'),
                'Expires: ' + expiry,
                'Requester key: ' + fingerprint,
              ].join('\n'),
              needsPassword: false,
              grant,
              awaitExecution: true,
              error: '',
            };
          },
          decision: (self, req) => _signDashboardAccessDecision(self, req),
        },
        fleet_machine_admission: {
          open(self, r) {
            const staged = r.staged;
            if (!staged || staged.v !== 1 || !staged.request ||
                !staged.channel_binding || !staged.verification_code ||
                !Number.isSafeInteger(staged.issued_at)) {
              throw new Error('fleet admission has no server-frozen request');
            }
            self.approvalBusy = false;
            self.approvalRequest = {
              id: r.id, kind: r.kind, session: 'Fleet invitation',
              title: 'Add this machine?', actionLabel: 'Approve machine',
              op: 'admit', target: 'New Dashboard',
              bodyMarkdown: [
                'Compare the code below with the code on the joining machine.',
                'Approve only when every group matches.',
              ].join('\n'),
              fleet: {
                verificationCode: staged.verification_code,
                requestId: staged.source_request_id,
                request: staged.request,
                channelBinding: staged.channel_binding,
                personalRootPub: staged.personal_root_pub,
                localBootstrapMachineId: staged.local_bootstrap_machine_id || null,
                issuedAt: staged.issued_at,
              },
              machineName: '',
              needsPassword: false,
              awaitExecution: true,
              error: '',
            };
          },
          decision: (self, req) => _signFleetAdmissionDecision(self, req),
        },
        // Secure-setting provisioning: the agent described a small form
        // (staged.fields); the operator fills it and the values are HPKE-
        // sealed IN THIS BROWSER to the server-frozen recipient key. The
        // decision carries only {nonce, sealed_payload} — the plaintext
        // never leaves this page.
        secure_setting: {
          open(self, r) {
            const staged = r.staged;
            const req = r.request || {};
            const workspaces = staged && staged.workspaces;
            if (!staged || !Array.isArray(staged.fields) || !staged.fields.length ||
                !staged.recipient_pub || !staged.nonce ||
                !Array.isArray(workspaces) || !workspaces.length ||
                !staged.purposes ||
                workspaces.some((ws) => typeof staged.purposes[ws] !== 'string')) {
              throw new Error('secure setting request has no server-frozen sealing context');
            }
            const lines = [req.description || ''];
            lines.push('', 'For: ' + (req.origin || 'unknown'),
              'Stored as: ' + (staged.target_key || '?') + ' (org ' + (staged.org || '?') + ')',
              'Decryptable ONLY by workspace' + (workspaces.length > 1 ? 's' : '') +
                ': ' + workspaces.join(', '),
              'Recipient key: ' + (staged.key_id || '?'),
              '', 'Values are sealed in your browser — the server stores only ciphertext.',
              'Widening the workspace list later requires re-provisioning here.');
            self.approvalBusy = false;
            self.approvalRequest = {
              id: r.id, kind: r.kind, session: r.session,
              title: req.title || 'Provide a secure setting',
              actionLabel: 'Seal & save',
              op: 'seal', target: staged.target_key || '',
              bodyMarkdown: lines.join('\n').trim(),
              secure: {
                fields: staged.fields.map((f) => ({
                  label: f.label, key: f.key, secret: f.secret !== false,
                  placeholder: f.placeholder || '', value: '', show: false,
                })),
                recipientPub: staged.recipient_pub,
                purposes: staged.purposes,
                workspaces,
                nonce: staged.nonce,
              },
              awaitExecution: true,
              error: '',
            };
          },
          async decision(self, req) {
            const s = req.secure;
            const payload = {};
            for (const f of s.fields) {
              if (!f.value) throw new Error('Fill in “' + f.label + '” before approving.');
              payload[f.key] = f.value;
            }
            const sealing = await import('../ceremony/sealing.js');
            const plaintext = new TextEncoder().encode(JSON.stringify(payload));
            const sealedPayloads = {};
            for (const ws of s.workspaces) {
              const record = await sealing.sealToEncapsulationKey(
                plaintext, s.recipientPub, s.purposes[ws]);
              sealedPayloads[ws] = Array.from(record)
                .map((b) => b.toString(16).padStart(2, '0')).join('');
            }
            return { nonce: s.nonce, sealed_payloads: sealedPayloads };
          },
        },
        commit_sign: {
          async open(self, r) {
            // Render the pending commit in THIS overlay, in sign mode.
            self.signPassphrase = ''; self.signing = false; self.signError = null;
            self.signPrompt = false; self.signRemember = false;
            self.signHasRemembered = !!(await self._rememberedPassphrase());
            const parsed = _parseCommitPayload(new TextDecoder().decode(_b64ToBytes(r.request.payload_b64)));
            self.selectedCommit = {
              row: { session_name: r.session, repo_name: r.request.repo, session_live: true },
              commit: {
                sha: null, subject: parsed.subject, body: parsed.body, author: parsed.author,
                files: r.files || [], patch: r.patch || '',
                stats: _commitStats({ files: r.files || [] }),
              },
              patchFiles: _patchIndex(r.patch || ''),
              commitIndex: 0, position: 1, total: 1, pr: null,
              signMode: true, approvalId: r.id, payloadB64: r.request.payload_b64,
            };
            self.showDiff = true;
          },
        },
      },

      // Ids we have seen decided, by anyone on any client. The server round-trip
      // below cannot close the race on its own: a re-delivered approval:pending
      // that arrives while the decision is in flight still reads result === null
      // and re-opens the overlay. This set is the local memory that makes a
      // retransmit a no-op regardless of timing.
      _decidedApprovals: null,
      _openingApprovals: null,

      _markApprovalDecided(id) {
        if (!id) return;
        if (!this._decidedApprovals) this._decidedApprovals = new Set();
        this._decidedApprovals.add(id);
        // Dismiss if this overlay is the one showing it — the decision may have
        // been made on another device, so this is not necessarily our own click.
        if (this.approvalRequest && this.approvalRequest.id === id) {
          this.approvalRequest = null;
        }
        if (this.selectedCommit && this.selectedCommit.approvalId === id) {
          this.selectedCommit = null;
        }
      },

      async openApprovalRequest(id) {
        if (this._decidedApprovals && this._decidedApprovals.has(id)) return;
        if ((this.approvalRequest && this.approvalRequest.id === id) ||
            (this.selectedCommit && this.selectedCommit.approvalId === id)) return;
        if (!this._openingApprovals) this._openingApprovals = new Set();
        if (this._openingApprovals.has(id)) return;
        this._openingApprovals.add(id);
        this.detailLoading = true;
        try {
          const r = await (await fetch('/api/approvals/' + encodeURIComponent(id))).json();
          if (r.result !== null) { this._markApprovalDecided(id); return; }
          const kind = this._approvalKinds[r.kind];
          if (!kind) throw new Error('unknown approval kind: ' + r.kind);
          await kind.open(this, r);
          // This is the transport-neutral applied/rendered acknowledgment.
          // A visible client may cancel the delayed OS fallback only after the
          // exact approval has been fetched and its kind-specific UI applied.
          if (document.visibilityState === 'visible' && window.AutonomyWebPush) {
            window.AutonomyWebPush.acknowledgeApproval(r.id).catch(() => {});
          }
        } catch (e) {
          _toast('Could not load the approval request: ' + (e.message || e), 'error');
        } finally {
          this._openingApprovals.delete(id);
          this.detailLoading = false;
        }
      },

      // The pinned Sign button. If a passphrase is already remembered for this
      // session, sign in one tap; otherwise reveal the passphrase entry step.
      async onSignTap() {
        this.signError = null;
        const remembered = await this._rememberedPassphrase();
        if (remembered != null) {
          const ok = await this._doSign(remembered);
          if (!ok) { this.signHasRemembered = false; this.signPrompt = true; } // stored one was stale
          return;
        }
        this.signPrompt = true;
        this.$nextTick(() => { const el = this.$refs.signPassphraseInput; if (el) el.focus(); });
      },

      // Confirm from the passphrase entry step.
      async confirmSign() { await this._doSign(this.signPassphrase); },

      // Do the actual signing with a given passphrase. Returns true on success.
      async _doSign(passphrase) {
        const sc = this.selectedCommit;
        if (!sc || !sc.signMode) return false;
        this.signing = true; this.signError = null;
        try {
          const openpgp = await this._ensureOpenpgp();
          // Name the APPROVAL, not the organization: the server reads which
          // org from the request being signed, so the browser cannot select
          // somebody else's key and cannot get it wrong.
          const keyResp = await fetch('/api/sign-key?approval='
            + encodeURIComponent(sc.approvalId));
          const encArmored = await keyResp.text();
          if (!keyResp.ok || !encArmored
              || encArmored.indexOf('PRIVATE KEY') < 0) {
            // Say what the server said. This threw one generic sentence for
            // every distinct failure -- 404, 400, 500, auth -- so four
            // separate faults looked identical from the dialog and each
            // round trip produced no new information.
            throw new Error(
              (encArmored && encArmored.indexOf('PRIVATE KEY') < 0
                ? encArmored.trim()
                : 'the dashboard returned no signing key')
              + ' (HTTP ' + keyResp.status + ')');
          }
          const encPriv = await openpgp.readPrivateKey({ armoredKey: encArmored });
          // decryptKey throws on a wrong passphrase — so success here proves it.
          const priv = await openpgp.decryptKey({ privateKey: encPriv, passphrase });
          if (this.signRemember) { try { await this._rememberStore(passphrase); } catch (e) { /* non-fatal */ } }
          const bytes = _b64ToBytes(sc.payloadB64);   // sign the EXACT bytes
          const message = await openpgp.createMessage({ binary: bytes });
          const sig = await openpgp.sign({ message, signingKeys: priv, detached: true, format: 'armored' });
          const resp = await fetch('/api/approvals/' + encodeURIComponent(sc.approvalId) + '/decision', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ approved: true, signature: sig }),
          });
          if (!resp.ok) throw new Error('the dashboard rejected the signature');
          this.signPrompt = false;
          this._markApprovalDecided(sc.approvalId);
          _toast('Commit signed', 'success');
          return true;
        } catch (e) {
          this.signError = (e && e.message) ? e.message : String(e);
          return false;
        } finally {
          this.signing = false;
        }
      },

      // ── "Remember for this session": passphrase encrypted with a
      // non-extractable AES-GCM key (kept in IndexedDB so its raw bytes never
      // touch JS); ciphertext in sessionStorage.
      //
      // The lifetime IS the tab session — sessionStorage drops the ciphertext
      // on tab close, which is the bound the checkbox promises. There is no
      // additional timeout: re-entering the passphrase every few minutes buys
      // nothing once the tab already holds it, and the expiry only trained the
      // operator to retype it.
      _idb() {
        return new Promise((res, rej) => {
          const req = indexedDB.open('sign-remember', 1);
          req.onupgradeneeded = () => req.result.createObjectStore('k');
          req.onsuccess = () => res(req.result);
          req.onerror = () => rej(req.error);
        });
      },
      async _idbOp(mode, fn) {
        const db = await this._idb();
        return new Promise((res, rej) => {
          const store = db.transaction('k', mode).objectStore('k');
          const r = fn(store);
          r.onsuccess = () => res(r.result);
          r.onerror = () => rej(r.error);
        });
      },
      async _rememberStore(passphrase) {
        const key = await crypto.subtle.generateKey({ name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']);
        const iv = crypto.getRandomValues(new Uint8Array(12));
        const ct = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, new TextEncoder().encode(passphrase));
        await this._idbOp('readwrite', (s) => s.put(key, 'k'));
        sessionStorage.setItem('sign-remember', JSON.stringify({
          iv: Array.from(iv), ct: Array.from(new Uint8Array(ct)),
        }));
      },
      async _rememberedPassphrase() {
        try {
          const raw = sessionStorage.getItem('sign-remember');
          if (!raw) return null;
          const blob = JSON.parse(raw);
          const key = await this._idbOp('readonly', (s) => s.get('k'));
          if (!key) return null;
          const pt = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: new Uint8Array(blob.iv) }, key, new Uint8Array(blob.ct));
          return new TextDecoder().decode(pt);
        } catch (e) { return null; }
      },
      async _rememberClear() {
        try { sessionStorage.removeItem('sign-remember'); } catch (e) { /* ignore */ }
        try { await this._idbOp('readwrite', (s) => s.delete('k')); } catch (e) { /* ignore */ }
      },

      // Approve from the generic overlay. Kinds whose approval must carry
      // client-produced material (e.g. the session-key-signed registry
      // envelope for link_publish) declare a ``decision`` builder in
      // _approvalKinds; its return value is merged into the decision body.
      // Execution happens server-side afterwards; the requester receives
      // the outcome through the approval result.
      async approveRequest() {
        const req = this.approvalRequest;
        if (!req || this.approvalBusy) return;
        this.approvalBusy = true;
        req.error = '';
        const kindDef = this._approvalKinds[req.kind];
        let cleaned = false;
        try {
          const extra = (kindDef && kindDef.decision)
            ? await kindDef.decision(this, req) : {};
          const resp = await fetch('/api/approvals/' + encodeURIComponent(req.id) + '/decision', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ approved: true, ...extra }),
          });
          // Factor material has crossed its one chokepoint. Drop browser
          // references before waiting for the server-side open to finish.
          if (kindDef && kindDef.cleanup) {
            await kindDef.cleanup(this, req);
            cleaned = true;
          }
          const decisionResult = await resp.json().catch(() => ({}));
          if (!resp.ok || !decisionResult.ok) {
            throw new Error(decisionResult.error || 'This approval is no longer available.');
          }
          if (req.gate2 || req.op === 'revoke' || req.awaitExecution) {
            const outcomeResp = await fetch(
              '/api/approvals/' + encodeURIComponent(req.id) + '?wait=20');
            const outcome = await outcomeResp.json().catch(() => ({}));
            const execution = outcome.result && outcome.result.execution;
            if (!outcomeResp.ok || !execution || execution.ok !== true) {
              throw new Error((execution && execution.error) || outcome.error ||
                'The approval did not finish executing. Try again.');
            }
          }
          this._markApprovalDecided(req.id);
          _toast(req.op === 'revoke' ? 'Share link revoked'
            : (req.gate2 ? 'Share link published' : 'Approved'), 'success');
        } catch (e) {
          const message = e && e.message ? e.message : String(e);
          if (req.gate2 || req.op === 'revoke' || req.awaitExecution) req.error = message;
          else _toast('Could not approve: ' + message, 'error');
        } finally {
          if (!cleaned && kindDef && kindDef.cleanup) {
            try { await kindDef.cleanup(this, req); } catch (e) { /* zeroization is best-effort */ }
          }
          this.approvalBusy = false;
        }
      },

      async dismissApproval() {
        if (!this.approvalRequest || this.approvalBusy) return;
        // Cancel must RESOLVE the server row (decline), not just hide it — else
        // the pending request re-surfaces on every reload. Declining executes nothing.
        const req = this.approvalRequest;
        const id = req.id;
        const kindDef = this._approvalKinds[req.kind];
        if (kindDef && kindDef.cleanup) {
          try { await kindDef.cleanup(this, req); } catch (e) { /* best-effort */ }
        }
        this._markApprovalDecided(id);
        if (id) {
          try {
            await fetch('/api/approvals/' + encodeURIComponent(id) + '/decision', {
              method: 'POST', headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ approved: false }),
            });
          } catch (e) { /* best-effort */ }
        }
      },

      closeApprovalLayer() {
        const req = this.approvalRequest;
        if (!req || this.approvalBusy) return;
        if (req.gate2 && req.previewOpen) req.previewOpen = false;
        else this.dismissApproval();  // Escape resolves the row (decline), same as Cancel
      },

      approvalAuthorityAvailable() {
        return !!(this.approvalRequest && this.approvalRequest.gate2 &&
          _matchingApprovalAuthority(this.approvalRequest));
      },

      // Decline is identical for every approval kind, so it lives here in the
      // shell rather than in the per-kind handlers.
      async declineApproval() {
        const req = this.approvalRequest;
        const id = (req && req.id) ||
          (this.selectedCommit && this.selectedCommit.approvalId);
        if (!id) return;
        const kindDef = req && this._approvalKinds[req.kind];
        if (kindDef && kindDef.cleanup) {
          try { await kindDef.cleanup(this, req); } catch (e) { /* best-effort */ }
        }
        try {
          await fetch('/api/approvals/' + encodeURIComponent(id) + '/decision', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ approved: false }),
          });
        } catch (e) { /* best-effort */ }
        this._markApprovalDecided(id);
      },

      async openCommitAt(row, index, options) {
        const opts = options || {};
        const next = this.commitAt(row, index);
        if (!next) {
          this.selectedCommit = null;
          return;
        }

        const preserveShowDiff = !!opts.preserveShowDiff;
        this.selectedDirtyRow = null;
        this.confirmDiscardRow = null;
        this.detailLoading = true;
        this.mergeState = 'idle';
        this.mergeBurstActive = false;
        this.reviewTitlePinned = false;
        if (!preserveShowDiff) this.showDiff = false;

        this.selectedCommit = next;
        this.queueCommitStickyOffsets();
        this.queueBranchLayouts();
        this.queuePathMeasurements();
        this.queueReviewHeaderState();
        const requestKey = this.commitKey(next);

        try {
          const resp = await fetch(
            '/api/worktrees/' + encodeURIComponent(row.session_name) + '/' +
              encodeURIComponent(row.repo_name) + '/commits/' +
              encodeURIComponent(next.commit.sha),
          );
          const detail = await _jsonOrError(resp);
          if (!this.selectedCommit || this.commitKey(this.selectedCommit) !== requestKey) return;
          this.selectedCommit = {
            ...this.selectedCommit,
            commit: {
              ...next.commit,
              ...detail,
              files: detail.files || next.commit.files || [],
              stats: _commitStats(detail),
            },
            patchFiles: _patchIndex(detail.patch || ''),
          };
          this.queueCommitStickyOffsets();
          this.queueBranchLayouts();
          this.queuePathMeasurements();
          this.queueReviewHeaderState();
        } catch (err) {
          _toast('Commit detail failed: ' + (err.message || String(err)), 'error');
        } finally {
          if (this.selectedCommit && this.commitKey(this.selectedCommit) === requestKey) {
            this.detailLoading = false;
          }
        }
      },

      async selectCommit(item) {
        if (!item || !item.row) return;
        await this.openCommitAt(item.row, item.commitIndex || 0);
      },

      hasEarlierCommit() {
        return !!this.selectedCommit && this.selectedCommit.commitIndex > 0;
      },

      hasLaterCommit() {
        return !!this.selectedCommit && this.selectedCommit.commitIndex < (this.selectedCommit.total - 1);
      },

      async viewEarlierCommit() {
        if (!this.hasEarlierCommit()) return;
        await this.openCommitAt(this.selectedCommit.row, this.selectedCommit.commitIndex - 1, { preserveShowDiff: true });
      },

      async viewLaterCommit() {
        if (!this.hasLaterCommit()) return;
        await this.openCommitAt(this.selectedCommit.row, this.selectedCommit.commitIndex + 1, { preserveShowDiff: true });
      },

      async selectDirtyRow(row) {
        if (!row) return;
        this.selectedCommit = null;
        this.confirmDiscardRow = null;
        this.mergeState = 'idle';
        this.mergeBurstActive = false;
        this.reviewTitlePinned = false;
        this.showDiff = true;
        this.dirtyDetailLoading = true;
        this.selectedDirtyRow = {
          ...row,
          files: this.dirtyFiles(row),
          patchFiles: {},
        };
        this.queueCommitStickyOffsets();
        this.queuePathMeasurements();
        this.queueReviewHeaderState();
        const requestKey = this.rowKey(row);
        try {
          const resp = await fetch(
            '/api/worktrees/' + encodeURIComponent(row.session_name) + '/' +
              encodeURIComponent(row.repo_name) + '/changes',
          );
          const detail = await _jsonOrError(resp);
          if (!this.selectedDirtyRow || this.rowKey(this.selectedDirtyRow) !== requestKey) return;
          this.selectedDirtyRow = {
            ...row,
            files: detail.files || this.dirtyFiles(row),
            patchFiles: _patchIndex(detail.patch || ''),
          };
          this.queueCommitStickyOffsets();
          this.queuePathMeasurements();
          this.queueReviewHeaderState();
        } catch (err) {
          _toast('Dirty diff detail failed: ' + (err.message || String(err)), 'error');
        } finally {
          if (this.selectedDirtyRow && this.rowKey(this.selectedDirtyRow) === requestKey) {
            this.dirtyDetailLoading = false;
          }
        }
      },

      openDiscardConfirm(row) {
        if (!row) return;
        this.selectedCommit = null;
        this.selectedDirtyRow = null;
        this.rebaseRequiredDialog = null;
        this.confirmDiscardRow = row;
      },

      async syncBase(row) {
        if (!row || this.isSyncingBase(row)) return;
        const key = this.rowKey(row);
        this.syncingBase = { ...this.syncingBase, [key]: true };
        try {
          const resp = await fetch(
            '/api/worktrees/' + encodeURIComponent(row.session_name) + '/' +
              encodeURIComponent(row.repo_name) + '/sync-base',
            { method: 'POST' },
          );
          await _jsonOrError(resp);
          _toast('Worktree base synced to latest ' + this.targetBranch(row), 'warning');
          await this.refresh(false);
        } catch (err) {
          _toast('Sync failed: ' + (err.message || String(err)), 'error');
        } finally {
          const next = { ...this.syncingBase };
          delete next[key];
          this.syncingBase = next;
        }
      },

      openRebaseRequiredDialog(item, payload) {
        this.rebaseRequiredDialog = {
          row: item.row,
          message: payload.message || 'Rebase required before merge.',
          session_live: !!payload.session_live,
        };
      },

      async cherryPickCommit(row) {
        if (!row || this.cherryPicking) return;
        this.cherryPicking = true;
        let data;
        try {
          const resp = await fetch(
            '/api/worktrees/' + encodeURIComponent(row.session_name) + '/' +
              encodeURIComponent(row.repo_name) + '/cherry-pick',
            { method: 'POST' },
          );
          data = await _jsonOrError(resp);
        } catch (err) {
          _toast('Cherry-pick failed: ' + (err.message || String(err)), 'error');
          this.cherryPicking = false;
          return;
        }

        // Celebration sequence — must complete before refresh()/dismissal,
        // otherwise syncOverlayRows() can null selectedCommit while the
        // confetti template is still rendering and unmount the DOM mid-anim.
        this.mergeBurstSeed += 1;
        this.mergeBurstActive = true;
        const rowKey = this.rowKey(row);
        window.setTimeout(() => {
          this.poofingRowKey = rowKey;
        }, this._POOF_START_MS);
        window.setTimeout(() => {
          this.poofingRowKey = '';
        }, this._POOF_START_MS + this._POOF_DURATION_MS);
        window.setTimeout(async () => {
          this.mergeBurstActive = false;
          _toast('Cherry-picked ' + (data.commit || '').slice(0, 8) +
                 ' to ' + this.targetBranch(row), 'success');
          this.markCherryPickedRowLanded(row);
          this.selectedCommit = null;
          try {
            await this.refresh(false, { suppressErrorToast: true });
          } catch (_ignored) {
            // refresh() catches and returns false on failure.
          } finally {
            this.markCherryPickedRowLanded(row);
            this.selectedCommit = null;
            this.cherryPicking = false;
          }
        }, this._BURST_WINDOW_MS);
      },

      async requestRebase(row) {
        if (!row || this.rebaseRequesting) return;
        this.rebaseRequesting = true;
        // Optimistic local "awaiting" placeholder covers the gap between
        // this directive append and the first WorktreeRebaseStatusV1 write.
        // The strict ``rebaseRequesting`` guard above already debounces
        // in-flight POSTs; this also prevents a second click from
        // double-stamping the row's status while one POST is in flight.
        const key = this.rowKey(row);
        this._setRebaseStatus(key, { state: 'awaiting', error: '', optimistic: true });
        try {
          if (!this._RebaseDirective) {
            const Schema = (typeof window !== 'undefined') ? window.Schema : null;
            if (!Schema || typeof Schema.of !== 'function') {
              throw new Error('Schema.of unavailable');
            }
            this._RebaseDirective = await Schema.of(
              'dashboard.session.crosstalk.worktree.rebase',
            );
          }
          await this._RebaseDirective.append({
            target_session: row.session_name,
            repo: row.repo_name,
          });
          _toast('Rebase request sent to ' + row.session_name, 'warning');
          this.rebaseRequiredDialog = null;
          await this.refresh(false);
        } catch (err) {
          // The directive write itself failed — no action handler will run,
          // so clear the optimistic awaiting placeholder immediately.
          // Delivery failures after a successful write flow back through
          // WorktreeRebaseStatusV1 as ``failed``.
          this._clearRebaseStatus(key);
          _toast('Request Rebase failed: ' + (err.message || String(err)), 'error');
        } finally {
          this.rebaseRequesting = false;
        }
      },

      // ── Rebase status state machine ────────────────────────────
      //
      // Three concerns layered together:
      //
      // 1. Local optimistic state — set by ``requestRebase`` so the
      //    button immediately flips to "Awaiting agent..." for the
      //    operator the moment they click. Lives in ``rebaseStatus``
      //    keyed by ``rowKey(row)``.
      // 2. Agent-driven transitions — the agent writes
      //    ``WorktreeRebaseStatusV1`` (set_id
      //    ``dashboard.session.worktree.rebase_status``) at three
      //    points: ``in_progress`` on ack, ``done`` on success,
      //    ``failed`` with ``error`` on conflict. The substrate's
      //    ``setting.changed`` fires; this component reads the new
      //    payload via ``proxy.read(key)`` and updates state.
      // 3. UI side-effects — ``done`` re-opens the commit at the new
      //    SHA via ``openCommitAt`` (rebase changes the SHA, so a
      //    plain ``refreshSelectedRow`` would leave the diff stuck
      //    on the old SHA). ``failed`` toasts the error.
      rebaseStatusFor(row) {
        if (!row) return null;
        const entry = this.rebaseStatus[this.rowKey(row)];
        return entry ? entry.state : null;
      },

      rebaseErrorFor(row) {
        if (!row) return '';
        const entry = this.rebaseStatus[this.rowKey(row)];
        return entry ? (entry.error || '') : '';
      },

      _setRebaseStatus(key, entry) {
        if (!key) return;
        // Replace the whole map so Alpine reactivity sees the change
        // (mutating a single property on a nested object can miss the
        // re-render in some Alpine setups; copy-on-write is bulletproof).
        this.rebaseStatus = { ...this.rebaseStatus, [key]: entry };
      },

      _clearRebaseStatus(key) {
        if (!key) return;
        if (!(key in this.rebaseStatus)) return;
        const next = { ...this.rebaseStatus };
        delete next[key];
        this.rebaseStatus = next;
      },

      _rowForRebaseKey(key) {
        if (!key) return null;
        return this.rows.find((r) => this.rowKey(r) === key) || null;
      },

      // Subscription handler. Fired when the agent (or anyone) writes
      // to the WorktreeRebaseStatusV1 set. ``payload`` is the
      // ``setting.changed`` envelope: ``{set_id, schema_revision, key,
      // org, publication_state, deprecated, operation}``. The actual
      // payload requires a follow-up read.
      async _onRebaseStatusChanged(notify) {
        if (!this._RebaseStatusSchema || !notify || !notify.key) return;
        let entry;
        try {
          entry = await this._RebaseStatusSchema.read(notify.key);
        } catch (_err) {
          return;
        }
        if (!entry || !entry.payload) return;
        const state = entry.payload.state || '';
        const error = entry.payload.error || '';
        if (!state) return;
        // Agent transition wins over the optimistic local placeholder.
        this._setRebaseStatus(notify.key, { state, error, optimistic: false });
        await this._applyRebaseTransition(notify.key, state, error);
      },

      async _applyRebaseTransition(key, state, error) {
        if (state === 'done') {
          // Rebase changed the SHA — refetch the row and reopen the
          // commit at the same index so the diff matches the new SHA.
          // refreshSelectedRow alone re-fetches row data but leaves the
          // commit detail stuck on the old SHA. Order: refresh rows
          // first so commitAt(row, idx) finds the new commit list.
          try {
            await this.refresh(false);
          } catch (_err) {
            // refresh toasts on its own
          }
          if (this.selectedCommit && this.rowKey(this.selectedCommit.row) === key) {
            const row = this._rowForRebaseKey(key) || this.selectedCommit.row;
            const idx = this.selectedCommit.commitIndex || 0;
            await this.openCommitAt(row, idx, { preserveShowDiff: true });
          }
          return;
        }
        if (state === 'failed') {
          _toast('Rebase failed: ' + (error || 'unknown error'), 'error');
          return;
        }
        // 'in_progress' / other — no side effect; the button label
        // updates reactively from rebaseStatusFor().
      },

      async _initRebaseStatusSubscription() {
        const Schema = (typeof window !== 'undefined') ? window.Schema : null;
        if (!Schema || typeof Schema.of !== 'function') return;
        let proxy;
        try {
          proxy = await Schema.of('dashboard.session.worktree.rebase_status');
        } catch (err) {
          if (typeof console !== 'undefined' && console.warn) {
            console.warn('[worktrees] rebase_status schema bind failed:', err);
          }
          return;
        }
        this._RebaseStatusSchema = proxy;
        if (typeof proxy.onChange !== 'function') return;
        const unsub = proxy.onChange((notify) => this._onRebaseStatusChanged(notify));
        if (typeof unsub === 'function') this._rebaseStatusUnsubs.push(unsub);
      },

      async confirmDiscard() {
        const row = this.confirmDiscardRow;
        if (!row || this.isCleaningRow(row)) return;
        const key = this.rowKey(row);
        this.cleaning = { ...this.cleaning, [key]: true };
        try {
          const resp = await fetch(
            '/api/worktrees/' + encodeURIComponent(row.session_name) + '/' +
              encodeURIComponent(row.repo_name) + '/discard',
            { method: 'POST' },
          );
          const data = await _jsonOrError(resp);
          const removed = (data.removed || []).length;
          _toast('Discarded ' + removed + ' worktree' + (removed === 1 ? '' : 's'), 'warning');
          this.confirmDiscardRow = null;
          await this.refresh(false);
        } catch (err) {
          _toast('Discard failed: ' + (err.message || String(err)), 'error');
        } finally {
          const next = { ...this.cleaning };
          delete next[key];
          this.cleaning = next;
        }
      },

      async startMergeCommit() {
        const item = this.selectedCommit;
        if (!this.canMergeCommit(item) || this.mergeState !== 'idle') return;
        this.mergeState = 'working';
        try {
          const resp = await fetch(
            '/api/worktrees/' + encodeURIComponent(item.row.session_name) + '/' +
              encodeURIComponent(item.row.repo_name) + '/commits/' +
              encodeURIComponent(item.commit.sha) + '/merge',
            { method: 'POST' },
          );
          await _jsonOrError(resp);
          this.mergeState = 'success';
          this.mergeBurstSeed += 1;
          this.mergeBurstActive = true;

          const row = item.row;
          const rowKey = this.rowKey(row);
          // Row card fades out (poof) in parallel with the confetti, but
          // both have to finish before we mutate this.rows / null
          // selectedCommit. Doing the dismissal inside the poof's nested
          // setTimeout (940ms) cut the confetti's 820ms+60ms-delay
          // animation off mid-paint — selectedCommit going null unmounts
          // the entire commit-detail subtree where the confetti lives.
          window.setTimeout(() => {
            this.poofingRowKey = rowKey;
          }, this._POOF_START_MS);
          window.setTimeout(() => {
            this.poofingRowKey = '';
          }, this._POOF_START_MS + this._POOF_DURATION_MS);
          window.setTimeout(async () => {
            this.mergeBurstActive = false;

            const commits = this.commitList(row).slice();
            if (commits.length) {
              commits.shift();
              row.commits = commits;
              row.commits_ahead = commits.length;
              row.ff_eligible = commits.length > 0;
              row.rebase_required = false;
              this.rows = this.rows.slice();
              this.queueBranchLayouts();
              this.queuePathMeasurements();
            }

            this.mergeState = 'idle';
            _toast('Merged ' + (item.commit.short_sha || this.shortSha(item.commit.sha)), 'warning');

            if (commits.length) {
              await this.openCommitAt(row, 0, { preserveShowDiff: true });
            } else {
              this.selectedCommit = null;
            }
          }, this._BURST_WINDOW_MS);
        } catch (err) {
          this.mergeState = 'idle';
          this.mergeBurstActive = false;
          if (err && err.payload && err.payload.error === 'rebase_required') {
            this.openRebaseRequiredDialog(item, err.payload);
          } else {
            _toast('Merge failed: ' + (err.message || String(err)), 'error');
          }
          try {
            await this.refresh(false);
          } catch (_ignored) {
            // refresh already toasts on failure
          }
        }
      },

      init() {
        if (this._mode === 'overlay') {
          window._worktreeReviewOverlay = this;
          // GLOBAL approval surfacing: any pending approval foregrounds on ANY
          // screen (not only when its requesting session is being viewed).
          // openApprovalOverlay is idempotent, so a re-open is a no-op.
          this._globalApprovalHandler = (d) => {
            if (d && d.id && window.openApprovalOverlay) window.openApprovalOverlay(d.id);
          };
          // The server broadcasts approval:decided to every client, so a
          // decision taken on another device dismisses the overlay here too.
          // This page renders the overlay; without this handler it was the one
          // surface that never learned a request had been answered.
          this._globalApprovalDecidedHandler = (d) => {
            if (d && d.id) this._markApprovalDecided(d.id);
          };
          if (typeof window.registerHandler === 'function') {
            window.registerHandler('approval:pending', this._globalApprovalHandler);
            window.registerHandler('approval:decided', this._globalApprovalDecidedHandler);
          }
          this.loading = false;
        } else {
          this._restoreOrg();
          // Claim the global toolbar: hides the shared search box +
          // page-title and shows #app-topbar-slot, where this page's
          // org dropdown + Refresh are teleported. The SPA router's
          // resetTopbar() removes the class again on every navigation.
          const header = document.querySelector('header');
          if (header) header.classList.add('app-topbar-active');
          this.loadOrgs().then(() => this._initialLoad());
        }
        // Bind the agent-→dashboard rebase status channel. Failures
        // inside the bind log + return — the page still works without
        // it (the operator just loses the live "Rebasing..." spinner
        // and has to refresh manually).
        this._initRebaseStatusSubscription();
        this.$watch('selectedCommit', (value) => {
          if (!value) {
            this.reviewTitlePinned = false;
            this.disconnectCommitStickyObserver();
            this.disconnectReviewTitleObserver();
          }
          this.syncScrollLock();
        });
        this.$watch('selectedDirtyRow', (value) => {
          if (!value) {
            this.reviewTitlePinned = false;
            this.disconnectCommitStickyObserver();
            this.disconnectReviewTitleObserver();
          }
          this.syncScrollLock();
        });
        this.$watch('confirmDiscardRow', () => {
          this.syncScrollLock();
        });
        this.$watch('rebaseRequiredDialog', () => {
          this.syncScrollLock();
        });
        this._resizeHandler = () => {
          if (this.selectedCommit || this.selectedDirtyRow) this.queueCommitStickyOffsets();
          this.queueBranchLayouts();
          this.queuePathMeasurements();
          this.queueReviewHeaderState();
        };
        window.addEventListener('resize', this._resizeHandler);
        if (this._mode !== 'overlay') {
          this._timer = setInterval(() => {
            if (this.selectedCommit || this.selectedDirtyRow || this.confirmDiscardRow || this.mergeState !== 'idle') {
              return;
            }
            this.refresh(false);
          }, 30000);
        }
      },

      // Deeplink entry point. The session-viewer's workspace-changes
      // anchor lands here with ``?session=<tmux_name>``; auto-open the
      // review screen for that session — commits-ahead first (the
      // ready-to-merge case, opened at the oldest commit so the
      // review walks chronologically toward HEAD), falling back to
      // dirty-files when there are no commits. Multi-repo sessions:
      // take the first matching row; the operator can hop to
      // siblings via the in-page nav.
      async _initialLoad() {
        // Deeplinks (?session=<tmux>) must work regardless of which org
        // is selected: resolve the target session's org first, switch
        // to it, then load. Without a deeplink, load the persisted org
        // or fall through to the picker.
        const params = new URLSearchParams(window.location.search);
        const target = params.get('session');
        if (target) {
          try {
            const resp = await fetch('/api/worktrees');
            const all = _normalizeRows(await _jsonOrError(resp));
            const match = all.find((r) => r.session_name === target);
            const slug = match && match.org && match.org.slug;
            if (slug && slug !== this.selectedOrg) {
              this.selectedOrg = slug;
              try { localStorage.setItem('worktrees.org', slug); } catch (e) { /* private mode */ }
            }
          } catch (err) { /* fall through to the normal load */ }
        }
        if (!this.selectedOrg) {
          this.loading = false;
          return;
        }
        await this.refresh(false);
        await this._handleDeeplink();
      },

      async _handleDeeplink() {
        const params = new URLSearchParams(window.location.search);
        const target = params.get('session');
        if (!target) return;
        const matches = this.rows.filter((r) => r.session_name === target);
        if (!matches.length) return;
        const withPrs = matches.find((r) => this.rowPrs(r).length > 0);
        if (withPrs) {
          await this.openReviewDefault(withPrs);
          return;
        }
        const withCommits = matches.find((r) => (this.commitList(r) || []).length > 0);
        if (withCommits) {
          await this.openReviewDefault(withCommits);
          return;
        }
        const dirtyMatch = matches.find((r) => r.is_dirty);
        if (dirtyMatch) this.selectDirtyRow(dirtyMatch);
      },

      destroy() {
        if (window._worktreeReviewOverlay === this) {
          window._worktreeReviewOverlay = null;
        }
        if (this._globalApprovalHandler && typeof window.unregisterHandler === 'function') {
          window.unregisterHandler('approval:pending', this._globalApprovalHandler);
          this._globalApprovalHandler = null;
          if (this._globalApprovalDecidedHandler) {
            window.unregisterHandler('approval:decided', this._globalApprovalDecidedHandler);
            this._globalApprovalDecidedHandler = null;
          }
        }
        this.disconnectCommitStickyObserver();
        this.disconnectReviewTitleObserver();
        document.documentElement.style.overflow = '';
        document.body.style.overflow = '';
        if (this._timer) {
          clearInterval(this._timer);
          this._timer = null;
        }
        if (this._resizeHandler) {
          window.removeEventListener('resize', this._resizeHandler);
          this._resizeHandler = null;
        }
        for (const u of (this._rebaseStatusUnsubs || [])) {
          try { u(); } catch (_) {}
        }
        this._rebaseStatusUnsubs = [];
      },
    }));
  });

  window.openWorktreeReviewOverlay = async function (sessionName) {
    if (!window._worktreeReviewOverlay || typeof window._worktreeReviewOverlay.openSessionOverlay !== 'function') {
      return false;
    }
    return await window._worktreeReviewOverlay.openSessionOverlay(sessionName);
  };

  window.openCommitOverlay = async function (opts) {
    if (!window._worktreeReviewOverlay || typeof window._worktreeReviewOverlay.openCommitOverlay !== 'function') {
      return false;
    }
    return await window._worktreeReviewOverlay.openCommitOverlay(opts);
  };

  window.openApprovalOverlay = async function (id) {
    if (!window._worktreeReviewOverlay || typeof window._worktreeReviewOverlay.openApprovalRequest !== 'function') {
      return false;
    }
    await window._worktreeReviewOverlay.openApprovalRequest(id);
    return true;
  };
})();
